(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["es"] = {"ui":{"lead":"¿Cómo se encontraron, olvidaron, descifraron y transformaron los juegos? Lee {n} historias y acierta todas las preguntas del cuestionario final para ganar un sello.","card":"Tarjeta de sellos","cardN":"{n} de {of} conseguidos","cardAll":"¡Todos conseguidos!","no":"Historia {n}","mins":"{n} min","stamped":"Sellado","back":"Todas las historias","quiz":"Cuestionario","links":"Ver y jugar","game":"Juego","exhibit":"Colección","art":"Pintura","room":"Sala","room_chance":"Azar","qn":"Pregunta {n} de {of}","right":"¡Correcto!","wrong":"Casi… la respuesta correcta está marcada.","got":"¡Sellado!","again":"¡Todo correcto!","gotSub":"Ya está en tu tarjeta de sellos.","missed":"{n} fallos","retrySub":"Acierta todas las preguntas para ganar el sello. Vuelve a leer la historia e inténtalo de nuevo.","retry":"Reintentar","room_paint":"En el arte","room_map":"Mapa","kfH":"Puntos clave","tlH":"Cronología","refH":"Fuentes y lecturas","picLink":"abre la página del museo"},"ex":{"ur":"Tablero del Juego Real de Ur","liubo":"Tablero y piezas de liubo","pyrgus":"Torre de dados romana","sugoroku":"Tablero de sugoroku del Shōsōin","nishapur":"Ajedrez de Nishapur","lewis":"Piezas de ajedrez de Lewis","senet":"Caja de senet de Tutankamón","ballinderry":"Tablero de Ballinderry","goose":"Tablero de ajedrez y de la oca","kofukuji":"Piezas de shogi de Kōfuku-ji","shosoin":"Tablero de go del Shōsōin"},"paint":{"liubo":"Dos figuras jugando al liubo","sugoroku":"Dos muchachas jugando al sugoroku","shahnama":"Buzurgmihr descifra el ajedrez","nefertari":"La reina Nefertari jugando al senet","chaupar":"Shiva y Parvati jugando al chaupar","shogi":"Pareja joven jugando al shogi","hydria":"Aquiles y Áyax jugando a un juego de tablero (hidria)","eakins":"Los jugadores de ajedrez","weiqi":"Plato con inmortales jugando al weiqi","webb":"Los jugadores de backgammon (armario)","liberale":"Los jugadores de ajedrez","mirror":"Estuche de espejo con una pareja jugando al ajedrez","morris":"Un tablero de juego (el molino)","leifeng":"Juego de tablero de la pagoda Leifeng","teniers":"Partida de backgammon","imari":"Plato con dos hombres jugando al go","shoei":"Las cuatro artes","tutinama":"El mono muerde al príncipe, su compañero de ajedrez (mogol, h. 1560)"},"ur":{"title":"Cómo un juego de 4.500 años recuperó sus reglas","lead":"El tablero de las tumbas reales de Ur llegó sin instrucciones. La pista estaba en una tablilla escrita dos mil años después.","s":["En la década de 1920, Leonard Woolley excavó las tumbas reales de Ur, en el sur de Irak, y halló un tablero de veinte casillas con incrustaciones de concha y lapislázuli, de hacia 2600–2400 a. C. Han aparecido tableros parecidos por todo Oriente Próximo: el juego se jugó mucho y durante largo tiempo.","Pero con ellos no apareció nada que explicara cómo jugar. Tablero, piezas y dados, y ninguna regla: un problema habitual con los juegos antiguos.","La pista estaba en los almacenes del Museo Británico: una tablilla cuneiforme copiada en 177/176 a. C. por el escriba babilonio Itti-Marduk-balāṭu a partir de una tablilla de un tal Iddin-Bēl. Se escribió más de dos mil años después del tablero.","A comienzos de los años ochenta, Irving Finkel, del Museo Británico, se dio cuenta de que la tablilla describía el mismo juego de veinte casillas. Su reverso muestra el tablero, con presagios para cada casilla en la que se cae. A partir de la tablilla y del propio tablero, Finkel reconstruyó un juego de carreras para dos.","Su reconstrucción se juega hoy en todo el mundo. Nadie puede asegurar que en Ur se jugara exactamente así. Aun así, en Kochi, al sur de la India, se jugaba un juego parecido hasta los años cincuenta: señal de lo larga que fue su vida."],"quiz":[["¿Cuándo se escribió la tablilla que dio las reglas?","En el siglo II a. C., más de 2.000 años después del tablero","Hacia 2600 a. C., como el tablero","En la Edad Media (siglo XII)","En el siglo XIX"],["¿Quién descifró la tablilla y reconstruyó las reglas?","Irving Finkel","Howard Carter","Jean-François Champollion","Arthur Evans"],["¿Qué dice la tablilla sobre caer en las casillas?","Presagios de buena o mala suerte","Nombres de reyes","Cantidades de impuestos","Solo nombres de estrellas"]],"kf":["Los tableros son de hacia 2600–2400 a. C., de las tumbas reales de Ur, en el sur de Irak","Las reglas se reconstruyeron a partir de una tablilla escrita más de 2.000 años después","20 casillas, siete piezas por bando, dados de cuatro caras"],"more":[{"h":"Tumbas reales y un «juego real»","p":["Woolley no halló uno, sino varios tableros de veinte casillas en el Cementerio Real de Ur. El más conocido, hoy en el Museo Británico, es de madera con incrustaciones de concha, caliza roja y lapislázuli, y dio nombre al juego: «el Juego Real de Ur».","Pero no era un juego solo de reyes. Tableros iguales aparecen desde Mesopotamia hasta Egipto y el Mediterráneo oriental, y en un palacio asirio incluso se grabó uno en la base de un gran toro alado con cabeza humana que guardaba una puerta, al parecer obra de los guardias."],"cap":["El Juego Real de Ur del Museo Británico; gíralo en 3D en la sala Colección"]},{"h":"Cómo funciona el tablero","p":["Las veinte casillas son un bloque de doce (3×4) y otro de seis (3×2) unidos por un estrecho «puente» de dos. Cinco casillas llevan una roseta; en las reglas reconstruidas, caer en una da otra tirada y es una casilla donde no te pueden capturar.","Los dados son tetraedros con dos de sus cuatro puntas marcadas. Se lanzan cuatro y se avanza según cuántas puntas marcadas queden arriba: de 0 a 4. Lo más frecuente es 2 (6 de 16); 0 y 4 salen solo 1 de cada 16. Puedes lanzarlos en la sala «Azar» del museo."],"cap":["Las veinte casillas y las cinco rosetas. Los números verdes son el camino de un jugador, casilla a casilla (reglas reconstruidas)","Cómo caen cuatro dados tetraédricos (de 16 formas igual de probables)"]},{"h":"Lo que dice la tablilla","p":["El anverso explica el juego; el reverso dibuja el tablero con signos del zodiaco en las casillas. Las frases para cada casilla suenan a augurios —«encontrarás un amigo», «beberás buena cerveza»—, así que el juego estaba unido a la suerte.","Pero la tablilla está rota en parte y no todas las reglas se pueden leer. La reconstrucción de Finkel arma el juego más coherente con las líneas legibles y la forma del tablero; otros estudiosos han propuesto otras versiones."]},{"h":"Los últimos jugadores, en la India","p":["Finkel supo después que la comunidad judía de Kochi (Cochín), en el sur de la India, había jugado hasta hace muy poco un juego de veinte casillas en un tablero de forma muy parecida.","Se transmitió en sus casas hasta que se trasladaron a Israel en los años cincuenta. Quizá el juego llegó a la India por antiguas rutas comerciales y sobrevivió más de cuatro mil años."]}],"tl":[["h. 2600–2400 a. C.","Se depositan tableros de veinte casillas en las tumbas reales de Ur"],["Siglo VIII a. C.","Se graba un tablero en la base de un guardián de puerta de un palacio asirio"],["177/176 a. C.","Un escriba babilonio copia la tablilla con las reglas"],["1922–1934","Woolley excava Ur y halla los tableros"],["Principios de los años ochenta","Finkel lee la tablilla y reconstruye las reglas"],["Hasta los años cincuenta","Se juega un juego muy parecido en Kochi, en el sur de la India"]]},"liubo":{"title":"¿Por qué desapareció el liubo?","lead":"Bajo los Han lo jugaban desde el emperador hasta el pueblo. En pocos siglos se olvidaron hasta sus reglas.","s":["El liubo fue la gran pasión de la China Han (206 a. C. – 220 d. C.). Aparece en figuras funerarias, relieves de piedra e incluso en la decoración de espejos, y a menudo se representa a seres inmortales jugándolo.","Tras la caída de los Han, el liubo decayó deprisa y, al parecer, en la dinastía Tang ya se habían perdido sus reglas. No se sabe bien por qué; una opinión es que los jugadores se pasaron a otros juegos, como el weiqi (go).","Sobrevivieron los tableros y los utensilios. Los tableros llevan un dibujo característico de formas en T, L y V, y las jugadas probablemente se decidían lanzando palillos finos. El mismo dibujo adorna los llamados espejos TLV.","También se van reuniendo pistas escritas. En 1993 apareció en una tumba Han de Yinwan (Jiangsu) un texto adivinatorio que usa el diagrama del tablero. La tumba de Liu He, marqués de Haihun, excavada en la década de 2010, dio más de mil tablillas de bambú sobre el liubo, que aún se estudian.","El liubo del Atlas es una reconstrucción basada en esas pistas. Los especialistas lo reconstruyen de formas algo distintas y las reglas verdaderas aún no se conocen del todo: nuevos hallazgos podrían cambiar su forma de jugarse."],"quiz":[["¿En qué dinastía fue enormemente popular el liubo?","Han","Ming","Qing","Song"],["¿Dónde se hallaron más de mil tablillas de bambú sobre el liubo?","En la tumba de Liu He, marqués de Haihun","En el mausoleo del Primer Emperador","En las cuevas de Dunhuang","En la Ciudad Prohibida"],["¿Qué se lanzaba probablemente para decidir las jugadas del liubo?","Palillos finos","Un dado de veinte caras","Una peonza","Cartas con dibujos"]],"kf":["Muy popular en China desde los Reinos Combatientes hasta los Han (s. V a. C. – s. III d. C.)","Un tablero con líneas en forma de T, L y V; se lanzaban palitos para mover","Decayó deprisa tras la caída de los Han y sus reglas aún no se conocen del todo"],"more":[{"h":"El tablero TLV","p":["El tablero de liubo es cuadrado, con un cuadrado en el centro, una T en medio de cada lado, formas de L a su alrededor y de V en las esquinas. Se cree que las piezas avanzaban por estas líneas y entre ellas.","Las mismas líneas aparecen en el dorso de espejos («espejos TLV») y en relojes de sol. Algunos estudiosos ven el tablero como un mapa del cosmos —cielo, tierra y los cuatro rumbos—, señal de que el liubo era más que un pasatiempo."],"cap":["Las líneas de un tablero de liubo (patrón TLV): un cuadrado central, una T en cada lado, formas de L y V hacia las esquinas"]},{"h":"Cómo se jugaba","p":["La mayoría de los estudiosos cree que cada jugador tenía seis piezas y lanzaba finos palitos de bambú para decidir el movimiento. El «seis» (liu) del nombre vendría de esos seis palitos o seis piezas.","Una pieza que avanzaba parece que se convertía en un poderoso «búho» (xiao). Un poema de hacia el siglo III a. C., «Invocación del alma» de los Cantos de Chu, dice: «hecho búho, se lanza y grita “¡cinco blancos!”». Los textos describen también un modo de juego en que las piezas pescaban «peces» en el «agua» del centro."],"cap":["Dos figuras jugando al liubo, hechas para una tumba Han (Museo Metropolitano de Arte)"]},{"h":"Juegos de las tumbas","p":["La tumba 3 de Mawangdui, en Changsha (Hunan), de hacia el 168 a. C., guardaba un juego completo —tablero, piezas y palitos— en una caja lacada, para que el difunto pudiera jugar en el más allá.","Los relieves de las paredes de las tumbas muestran a menudo a inmortales jugando al liubo en cumbres. El juego estaba unido al mundo de los inmortales y la larga vida."],"cap":["El tablero de liubo del museo; míralo en 3D en la sala Colección"]}],"tl":[["s. V–III a. C. (Reinos Combatientes)","Los tableros de liubo empiezan a ponerse en tumbas"],["h. s. III a. C.","«Invocación del alma» describe una partida de liubo"],["h. 168 a. C.","Un juego completo entra en la tumba 3 de Mawangdui"],["206 a. C. – 220 d. C. (Han)","Lo juegan emperadores y gente común; aparece en relieves y espejos"],["Tang (s. VII–X)","Se cree que las reglas ya se habían olvidado"],["1993","Aparece en las tumbas Han de Yinwan un texto adivinatorio con el tablero"],["Años 2010","Tablillas de bambú sobre el liubo en la tumba del marqués de Haihun, Liu He"]]},"zeno":{"title":"La tirada desafortunada del emperador Zenón","lead":"Hace mil quinientos años un emperador lanzó los dados, y el resultado sobrevive en un poema.","s":["Los romanos adoraban la tabula, un juego de carreras con dados sobre un tablero de 24 puntas: el antepasado del backgammon. Para evitar tiradas tramposas usaban incluso torres de dados, por cuyo interior caían rodando.","Hacia el año 480, el emperador romano de Oriente Zenón jugaba a la tabula. Sus tres dados marcaron 2, 5 y 6. No tuvo más remedio que mover como mandaban las reglas, y en su tablero quedaron ocho piezas solas y desprotegidas.","La partida la registró Agatías, historiador y poeta del siglo VI que vivió unas décadas después de Zenón. Su breve poema (un epigrama) da la posición de las piezas: un raro testimonio de una partida antigua.","En el siglo XIX, el estudioso francés Becq de Fouquières dedujo del poema la posición y las reglas: quince piezas por jugador y tres dados. Todas las piezas empiezan fuera del tablero y ambos jugadores avanzan en el mismo sentido.","Frente al backgammon actual, la tabula usaba tres dados, empezaba sin piezas en el tablero y no tenía cubo doblador. Gracias a la mala suerte de un emperador podemos ver cómo era la tabula."],"quiz":[["¿Qué sacó Zenón?","2, 5 y 6","6, 6 y 6","1, 1 y 1","3, 4 y 5"],["¿Quién dejó la partida escrita en un poema?","Agatías","Homero","Plinio","Cicerón"],["¿Cuál es una diferencia entre la tabula y el backgammon actual?","La tabula usaba tres dados","Treinta piezas por jugador","Un tablero de 12 puntas","Las piezas avanzan hacia atrás"]],"kf":["La tabula se jugaba con 24 puntos y tres dados: un antepasado del backgammon","La partida del emperador Zenón, hacia el año 480, sobrevive con su posición en un poema","Los romanos llegaron a construir «torres de dados» contra las trampas"],"more":[{"h":"El tablero de la tabula","p":["El tablero de la tabula, como el del backgammon actual, tiene 24 puntos en dos filas de 12. Cada jugador tenía quince piezas, todas fuera al empezar; según tres dados se metían, daban la vuelta y se sacaban.","La gran diferencia con el backgammon es que los dos jugadores avanzan en el mismo sentido. Una pieza sola podía ser golpeada si el rival caía en su punto y tenía que volver a entrar. Las ocho de Zenón eran justamente piezas así."],"cap":["Un tablero de tabula: 24 puntos en dos filas de 12; las piezas de ambos avanzan en el mismo sentido (flecha)"]},{"h":"Un aparato contra las trampas","p":["A los romanos les apasionaban los dados. Las leyes prohibían apostar, y se dice que solo se permitía durante la fiesta invernal de las Saturnales, pero las apuestas nunca cesaron, ni las trampas con los dedos.","De ahí la torre de dados: los dados que se echan por arriba chocan con tablillas interiores y salen rodando por abajo. Una del siglo IV hallada en una villa de Alemania lleva calado «Los pictos vencidos, el enemigo destruido: jugad tranquilos»."],"cap":["La torre de dados de Vettweiß-Froitzheim (siglo IV); mírala en 3D en la sala Colección"]},{"h":"Emperadores y dados","p":["Zenón no fue el único. Según el historiador Suetonio, el emperador Claudio, en el siglo I, adoraba los dados: escribió un libro sobre ese arte y hizo adaptar su carruaje para que el tablero no se moviera mientras jugaba.","En los yacimientos romanos aparecen también muchos tableros de 36 letras en palabras de seis; cada letra hacía de casilla, y algunos llevan burlas como «Levántate, no sabes jugar; deja sitio a un jugador»."],"cap":["Tablas y dados eran un placer de emperadores a soldados (lanza dados cúbicos en la sala Azar)"]}],"tl":[["Siglo I","El emperador Claudio escribe un libro sobre los dados"],["Siglo IV","Se usa una torre de dados en una villa de Alemania"],["h. 480","La desafortunada partida del emperador Zenón"],["Siglo VI","Agatías pone la partida en verso"],["h. siglo X","El poema se recoge en la Antología griega"],["1869","Becq de Fouquières reconstruye la posición y las reglas"],["1934","R. G. Austin reexamina en detalle la partida de Zenón"]]},"sugoroku":{"title":"El sugoroku prohibido","lead":"Los emperadores lo prohibían y la gente seguía jugando. La historia del sugoroku de tablero en Japón, de la Antigüedad al periodo Edo.","s":["El tesoro del Shōsōin conserva un tablero de sugoroku que, según la tradición, fue uno de los favoritos del emperador Shōmu. No es el sugoroku de papel con dibujos, sino el ban-sugoroku, que se juega moviendo piezas blancas y negras sobre un tablero: un pariente del backgammon.","El sugoroku estuvo ligado al juego de apuestas desde muy pronto. Según el Nihon Shoki, la emperatriz Jitō lo prohibió en 689.","El Código Yōrō, vigente desde 757, también prohibía jugar al sugoroku a monjes y monjas. Las prohibiciones se repitieron una y otra vez, señal de que no se cumplían.","En la época Heian siguió siendo popular y aparece en El libro de la almohada y en La historia de Genji. El Cantar de Heike cuenta que el emperador retirado Shirakawa citó tres cosas que no podía dominar: las aguas del río Kamo, los dados del sugoroku y los monjes guerreros del monte Hiei.","Los grabados del periodo Edo aún muestran a jóvenes disfrutando del ban-sugoroku en casa. Pero hacia la era Meiji el juego de tablero casi había desaparecido, y «sugoroku» pasó a designar el juego de papel con dibujos."],"quiz":[["El ban-sugoroku, como el tablero del Shōsōin, es pariente de ¿qué juego?","El backgammon","El shogi","El go","Los naipes"],["Según el Nihon Shoki, ¿quién prohibió el sugoroku en 689?","La emperatriz Jitō","El emperador Shōmu","El emperador Kanmu","El emperador Meiji"],["Shirakawa no podía dominar el río Kamo, los monjes guerreros y… ¿qué?","Los dados del sugoroku","Las piezas de shogi","Las piedras de go","Una pelota de kemari"]],"kf":["El ban-sugoroku es pariente del backgammon y ya se jugaba en Japón en el siglo VII","Se prohibió una y otra vez por las apuestas, primero la emperatriz Jitō en 689","En la era Meiji ya casi no se jugaba, y «sugoroku» pasó a nombrar el juego de papel ilustrado"],"more":[{"h":"El tablero del Shōsōin","p":["El tablero del Shōsōin es de palisandro con finas incrustaciones de marfil y maderas teñidas. Tiene 24 puntos, doce por lado, con flores en el separador central.","El Shōsōin guarda también muchas piezas de sugoroku de vidrio y piedra. El ban-sugoroku usa quince piezas blancas y quince negras y dos dados: casi lo mismo que el backgammon. Se cree que llegó del nard persa a través de China."],"cap":["El tablero de sugoroku del Shōsōin, de palisandro con incrustaciones; juega en él en la sala Colección"]},{"h":"Cómo se juega","p":["Cada jugador coloca quince piezas en un orden fijo y avanza según dos dados. Blancas y negras giran en sentidos opuestos; gana quien junta antes todas sus piezas en los últimos seis puntos.","Una pieza sola puede ser golpeada y devuelta al inicio. Un punto con dos o más no admite al rival, así que el arte está en formar bloqueos. En la sala Colección puedes jugar así sobre el tablero del Shōsōin."],"cap":["Un tablero de ban-sugoroku (esquema): los 24 puntos y el blanco y el negro en sentidos opuestos"]},{"h":"Prohibiciones y modas","p":["Tras Jitō, el sugoroku se prohibió muchas veces más, porque no dejaba de haber quien lo perdía todo apostando. El shogunato de Kamakura también dictó leyes contra las apuestas al sugoroku.","Pero también era un refinamiento de la nobleza. Un tablero bello formaba parte del ajuar de la novia, y en la época Edo se hicieron lujosos tableros lacados. Odiado como herramienta de apuesta y amado como tesoro: el ban-sugoroku tuvo ambas caras."],"cap":["Ban-sugoroku en un cuadro de la época Edo (sala Juegos pintados)"]}],"tl":[["Siglo VII","El ban-sugoroku llega desde China"],["689","La emperatriz Jitō prohíbe el sugoroku (Nihon shoki)"],["Siglo VIII","El tablero de palisandro entra en el Shōsōin"],["757","Entra en vigor el código Yōrō, que lo veta a monjes y monjas"],["Periodo Heian","Aparece en El libro de la almohada y La historia de Genji"],["Siglo XII","El lamento de Shirakawa por «los dados del sugoroku» (Heike monogatari)"],["Periodo Edo","Se hacen lujosos tableros para el ajuar de las novias"],["Era Meiji","El ban-sugoroku casi deja de jugarse"]]},"queen":{"title":"Cómo la dama se convirtió en la pieza más fuerte","lead":"La pieza más poderosa de hoy empezó siendo un consejero que solo avanzaba una casilla en diagonal.","s":["El ajedrez viajó de la India a Persia y al mundo árabe. En la epopeya persa, el Shahnameh, el sabio Buzurgmihr resuelve el enigma del ajedrez enviado desde la India. En aquellos tableros, la pieza junto al rey era el fers, el consejero.","El fers solo se movía una casilla en diagonal: una pieza muy débil. En el juego de ajedrez del siglo XII de Nishapur (Irán) es un pequeño trono, más pequeño que el del rey.","Al llegar a Europa, el consejero se convirtió en reina; entre las piezas de Lewis del siglo XII hay reinas. Pero el nuevo nombre no cambió el movimiento: seguía siendo débil.","El gran cambio llegó a España a finales del siglo XV. Scachs d’amor («Ajedrez de amor»), un poema escrito en Valencia hacia 1475, se considera el primer testimonio de la dama moderna, que avanza cualquier distancia por filas, columnas y diagonales. Los libros de Lucena (1497) y Damiano (1512) difundieron la nueva regla por Europa.","No se sabe con certeza por qué la dama se volvió tan fuerte. Unos dicen que se buscaban partidas más rápidas; otros apuntan a la influencia de reinas poderosas como Isabel I. En cualquier caso, el cambio acercó mucho el ajedrez al juego actual."],"quiz":[["En el ajedrez persa y árabe, ¿qué pieza ocupaba el lugar de la dama?","El fers (consejero)","El elefante","El carro","El caballo"],["¿Cómo se movía el fers original?","Una casilla en diagonal","Cualquier distancia en línea recta","Saltaba dos casillas","No podía moverse"],["¿Dónde se escribió el poema con el primer testimonio de la dama moderna?","En Valencia, siglo XV","En la India, siglo VI","En Lewis, siglo XII","En Londres, siglo XIX"]],"kf":["La dama empezó como el «alferza» o fers persa y árabe (consejero), que solo se movía una casilla en diagonal","La dama fuerte moderna aparece por escrito en España hacia 1475","Los libros impresos difundieron las nuevas reglas por Europa en pocas décadas"],"more":[{"h":"El consejero débil","p":["El fers solo podía avanzar una casilla en diagonal, muy lejos de la dama de hoy, que cruza el tablero de punta a punta. El ajedrez de entonces era lento, y una partida podía durar horas.","El elefante (el alfil actual) solo saltaba dos casillas en diagonal. Un peón que llegaba a la última fila coronaba, pero solo en ese débil fers."],"cap":["Hasta dónde llegan el fers (izquierda) y la dama moderna (derecha)"]},{"h":"«Ajedrez de la dama» y «ajedrez rabioso»","p":["Con la nueva dama, en España se llamó a esta forma de jugar «ajedrez de la dama», y en Italia, por su furia, «scacchi alla rabbiosa» (ajedrez rabioso). Por la misma época el alfil pasó a deslizarse cualquier distancia en diagonal.","Con piezas más fuertes el juego se volvió rápido y feroz. Aparecieron libros sobre trampas que ganan en pocas jugadas y sobre secuencias fijas de apertura, y el ajedrez se convirtió en un juego para estudiar."],"cap":["Liberale da Verona, Los jugadores de ajedrez (h. 1475), pintado justo cuando nacía la nueva dama"]},{"h":"¿Por qué una dama?","p":["No se sabe con certeza por qué el consejero se convirtió en dama. Ver a la pieza junto al rey como su consorte quizá resultaba natural. En latín «fers» pasó a «fercia» y luego se la llamó «regina», reina.","También se discute por qué se hizo fuerte: quizá para acelerar las partidas, quizá porque era una época de reinas poderosas como Isabel I de Castilla. La historiadora Marilyn Yalom relacionó el cambio con la posición de la mujer en la Edad Media."],"cap":["La dama de las piezas de Lewis (siglo XII), todavía con el movimiento débil"]}],"tl":[["h. siglo VI","Nace en la India el chaturanga, antepasado del ajedrez"],["Siglos VII–IX","Se juega en Persia y el mundo árabe, con el fers junto al rey"],["h. siglo X","El ajedrez llega a Europa"],["Siglo XII","Las piezas de Lewis incluyen damas (aún débiles)"],["h. 1475","El poema valenciano Scachs d’amor recoge el nuevo movimiento"],["1497","Se imprime en España el libro de ajedrez de Lucena"],["1512","Sale en Italia el libro de Damiano y se difunden las reglas"]]},"senet":{"title":"Cómo el senet se convirtió en un viaje al más allá","lead":"Un juego que se jugó en Egipto durante casi tres mil años acabó representando el viaje del alma tras la muerte.","s":["El senet es un juego del antiguo Egipto en el que las piezas avanzan por un tablero de tres filas de diez casillas. En tumbas de la I Dinastía, hacia 3100 a. C., se han hallado fragmentos de lo que podrían ser tableros de senet. La realeza jugaba en cajas espléndidas; la gente común, en tableros grabados en la piedra.","Su nombre significa «paso». Desde el Reino Nuevo (hacia 1550 a. C.), el senet se asoció con el viaje del alma del difunto a través del más allá.","El capítulo 17 del Libro de los Muertos muestra al difunto jugando al senet contra un rival invisible. En la pared de la tumba de Nefertari, esposa de Ramsés II, la reina aparece ante un tablero de senet.","La tumba de Tutankamón contenía al menos cinco cajas de juego. Una de ellas, una gran caja de ébano y marfil, tiene el senet arriba y otro juego de veinte casillas en la otra cara.","Sin embargo, no se ha hallado ningún texto que explique las reglas por completo. En el siglo XX, Jéquier, Bell y Kendall (1978), entre otros, reconstruyeron cada uno una forma de jugar a partir de tableros, imágenes y fragmentos de textos. El senet del Atlas es una de esas formas basadas en la investigación."],"quiz":[["¿Qué significa el nombre «senet»?","Paso","El juego del rey","Treinta casas","Cruzar el río"],["En el Reino Nuevo, ¿con qué se asoció el senet?","Con el viaje del alma por el más allá","Con ritos para atraer la lluvia","Con planes de batalla","Con augurios de cosecha"],["¿Cuántas cajas de juego, como mínimo, había en la tumba de Tutankamón?","Cinco","Una","Dos","Cien"]],"kf":["Uno de los juegos de tablero más antiguos: las piezas corren por un tablero de 3 × 10 casillas","Su nombre significa «paso»; en el Imperio Nuevo se volvió el viaje del alma por el más allá","No se conservan las reglas; las formas de jugar actuales son reconstrucciones del siglo XX"],"more":[{"h":"Treinta casillas y las especiales","p":["El tablero de senet tiene tres filas de diez, treinta casillas. Se cree que las piezas iban de izquierda a derecha por la primera fila, de derecha a izquierda por la segunda y otra vez de izquierda a derecha por la tercera, trazando una S.","Las cinco últimas casillas solían llevar signos especiales. La 26 es la «casa bella», la 27 el «agua», y en la mayoría de las reconstrucciones la pieza que cae al agua retrocede. De la 28 a la 30 había números o dioses del más allá."],"cap":["Un tablero de senet. Las piezas avanzan en S; las cinco últimas casillas (26–30) llevan signos especiales"]},{"h":"Avanzar con palos","p":["En vez de dados se lanzaban cuatro palos, planos por un lado y redondos por el otro, o tabas de animales. Muchos estudiosos creen que se avanzaba según los lados planos hacia arriba, y que ninguno valía cinco.","Esa cuenta es exactamente la de los palos yut de la lejana Corea. Lánzalos en la sala Azar del museo y verás cuánto más salen unos números que otros."],"cap":["Palos de lanzar egipcios (lánzalos en la sala Azar)"]},{"h":"Las cajas de juego de Tutankamón","p":["La tumba de Tutankamón, abierta por Howard Carter en 1922, contenía al menos cinco cajas de juego. La mayor es de ébano y marfil, con un cajón para las piezas y los palos.","En esta época eran comunes las cajas con tablero por ambas caras: senet en una y, en la otra, el mismo juego de veinte casillas que el Juego Real de Ur. Se quería que el rey pudiera jugar a ambos en el otro mundo."],"cap":["La caja de senet de Tutankamón: mírala en 3D y juega en la sala Colección"]}],"tl":[["h. 3100 a. C.","Fragmentos de un tablero parecido al senet en una tumba de la I dinastía"],["h. 2600 a. C.","Pinturas de tumbas del Imperio Antiguo muestran a gente jugando"],["Desde h. 1550 a. C.","Imperio Nuevo: el senet se une al viaje al más allá"],["h. 1323 a. C.","Cinco cajas de juego en la tumba de Tutankamón"],["h. 1250 a. C.","Nefertari aparece pintada ante un tablero de senet"],["1922","Carter abre la tumba de Tutankamón"],["1978","Kendall publica una reconstrucción de las reglas"]]},"lewis":{"title":"Las piezas de ajedrez que salieron de la arena","lead":"Piezas medievales halladas en una isla escocesa en 1831, y otra del mismo taller que apareció en un cajón 188 años después.","s":["En 1831 se halló en la isla de Lewis, al noroeste de Escocia, un conjunto de piezas talladas sobre todo en marfil de morsa: 78 piezas de ajedrez, 14 fichas para juegos de tablero y una hebilla, 93 objetos en total.","No está claro dónde ni cómo se encontraron exactamente. Suele citarse la bahía de Uig, en la costa oeste, pero hay otras propuestas. Tampoco se sabe quién las enterró allí ni por qué.","Se cree que se tallaron a finales del siglo XII en la región de Trondheim, en Noruega: reyes, reinas pensativas, obispos, caballeros sobre caballos rechonchos y guardianes que muerden el borde del escudo, que se cree que representan a los berserkers de las sagas nórdicas.","Hoy 82 piezas están en el Museo Británico y 11 en el Museo Nacional de Escocia. Desde hace tiempo se dice que faltan algunas piezas para completar los juegos.","En 2019, un guardián que un anticuario de Edimburgo compró por solo 5 libras en 1964, y que la familia guardaba en un cajón, se identificó como obra del taller de las piezas de Lewis. Se vendió en Sotheby’s por 735 000 libras."],"quiz":[["¿En qué año se hallaron las piezas en Lewis?","1831","1066","1931","1700"],["¿De qué están hechas sobre todo las piezas?","De marfil de morsa","De mármol","De oro","De vidrio"],["¿En qué año se compró por 5 libras el guardián vendido en 2019?","1964","1831","1990","2018"]],"kf":["93 piezas y discos hallados en la isla de Lewis (Escocia) en 1831","Tallados sobre todo en marfil de morsa en Noruega, a finales del siglo XII","Hoy repartidos entre el Museo Británico y los Museos Nacionales de Escocia"],"more":[{"h":"Las 78 piezas de ajedrez","p":["Las 78 piezas son 8 reyes, 8 damas, 16 obispos, 15 caballeros, 12 guardianes y 19 peones: restos de al menos cuatro juegos.","Los obispos llevan mitra. El paso del «elefante» al obispo ocurrió en Europa, y las piezas de Lewis están entre sus primeros ejemplos. Algunos guardianes muerden el escudo; se cree que son berserkers, guerreros que luchaban en trance."],"cap":["Las piezas de Lewis (míralas en 3D en la sala Colección)","Las 78 piezas por tipo"]},{"h":"Marfil de morsa y mares del norte","p":["La mayoría son de marfil de morsa y unas pocas de diente de ballena. El marfil de morsa era un tesoro de los mares del norte, traído de Groenlandia y el norte de Noruega.","Lewis pertenecía entonces a las islas del rey de Noruega; pasó a Escocia por el Tratado de Perth en 1266. Cerca de la catedral de Trondheim se han hallado fragmentos tallados del mismo modo, una pista de dónde se hicieron."],"cap":[]},{"h":"La leyenda del hallazgo y la fama actual","p":["Circulan muchas versiones del hallazgo: una vaca que las sacó de la arena, o un vecino, Malcolm MacLeod. El descubridor las vendió pronto y, vía Edimburgo, el Museo Británico compró la mayor parte.","Con sus caras cómicas y enfurruñadas son hoy muy populares y sus réplicas se venden en todo el mundo. El ajedrez mágico de la película Harry Potter y la piedra filosofal (2001) usó piezas basadas en las de Lewis."],"cap":[]}],"tl":[["Finales del siglo XII","Se hacen las piezas en Noruega (cerca de Trondheim)"],["1266","El Tratado de Perth entrega las islas, entre ellas Lewis, a Escocia"],["1831","Se hallan juntas las 93 piezas en Lewis"],["1831–32","El Museo Británico compra 82"],["1888","El museo nacional escocés adquiere 11"],["2001","Aparecen en el ajedrez mágico de Harry Potter"],["2019","Un guardián comprado por 5 £ se vende por 735.000 £"]]},"tafl":{"title":"La huida del rey y una traducción equivocada","lead":"Las reglas del juego de tablero de los vikingos se dedujeron de un diario de viaje por Laponia del siglo XVIII.","s":["En el norte de Europa, en la época vikinga, se jugaba a juegos de tablero llamados tafl. Un rey en el centro y sus pocos defensores luchan contra un ejército mayor que los rodea: un juego de dos bandos desiguales.","Un tablero de madera del siglo X hallado en Ballinderry (Irlanda) en 1932 tiene 7×7 agujeros, con el centro y las cuatro esquinas marcados: se cree que son el lugar del rey y su refugio.","Pero casi no se conserva ninguna descripción medieval de las reglas. Una pista clave es el diario del naturalista Linneo, de 25 años, de su viaje por Laponia (norte de Suecia) en 1732. Allí anotó cómo jugaban los sami a un juego llamado tablut.","El diario se publicó traducido al inglés en 1811, pero la traducción tenía errores. La reconstrucción de Murray (1913), basada en ella, fue durante muchos años la regla estándar del tafl.","Más tarde, jugadores e investigadores corrigieron el error, y hoy se juegan muchas versiones de las reglas. El tafl del Atlas es una de ellas."],"quiz":[["¿Qué juego anotó Linneo en Laponia?","El tablut","El senet","El mancala","El ajedrez"],["¿Qué pieza intentan llevar los defensores a una esquina?","El rey","La reina","Una bandera","Un barco"],["¿Cuándo se publicó la traducción inglesa con el error?","1811","1732","1932","1066"]],"kf":["Un rey y unos pocos defensores en el centro, rodeados por un ejército mayor: un juego de dos bandos desiguales","Se jugaba en el norte de Europa en la época vikinga, en tableros de 7×7 hasta 19×19","Las reglas nos llegan por el diario de viaje de Linneo de 1732… y por su traducción inglesa con errores"],"more":[{"h":"El tablero de Ballinderry","p":["Hallado en una vivienda lacustre (crannog) del centro de Irlanda, el tablero de Ballinderry es de tejo. Sus 49 agujeros, en una cuadrícula de 7×7, probablemente sujetaban piezas con una espiga en la base.","Del marco sale un asa tallada en forma de cabeza humana: era un tablero para llevar. Las fuentes irlandesas mencionan un tafl de 7×7, el brandubh («cuervo negro»), que bien pudo jugarse en él."],"cap":["El tablero de Ballinderry (7×7) con la posición inicial del brandubh irlandés. Los anillos dorados marcan el centro y las cuatro esquinas"]},{"h":"El tablut de Linneo","p":["El tablut que anotó Linneo usa un tablero de 9×9. El rey está en el trono central; sus 8 «suecos» se enfrentan a 16 «moscovitas».","Todas las piezas se mueven en línea recta cuantas casillas quieran, como una torre, y se capturan atrapándolas entre dos enemigas. Los defensores ganan si el rey llega al borde; los atacantes, si lo rodean por los cuatro lados. Linneo escribió mezclando latín y sueco, y varios puntos cambiaron en la traducción inglesa."],"cap":["El tablut tal como lo anotó Linneo (9×9): el rey en el trono central, 8 defensores y 16 atacantes. Los defensores ganan si el rey llega a una casilla verde del borde"]},{"h":"Tableros que crecen, un juego que se apaga","p":["Además del 7×7 había tableros de 9×9, el galés de 11×11 e incluso de 19×19. El mayor, el Alea Evangelii, aparece dibujado en un manuscrito del siglo XII que dice que vino de la corte del rey Æthelstan de Inglaterra, en el siglo X.","Cuando el ajedrez se extendió por el norte de Europa en los siglos XII y XIII, el tafl fue cayendo en desuso. Solo en la lejana Laponia sobrevivió el tablut, y Linneo lo anotó por casualidad. Hoy se juegan torneos internacionales en tableros de 11×11 y el juego gana nuevos jugadores."],"cap":["El tesoro de Lewis (siglo XII): junto a las piezas de ajedrez había 14 discos para un juego de tablero"]}],"tl":[["s. X","Se fabrica en Irlanda el tablero de Ballinderry"],["924–939","Se dice que en la corte de Æthelstan se jugaba al Alea Evangelii"],["s. XII","El Alea Evangelii se dibuja en un manuscrito"],["ss. XII–XIII","El ajedrez se extiende por el norte de Europa y el tafl desaparece"],["1732","Linneo anota el tablut en Laponia"],["1811","Sale Lachesis Lapponica, la traducción inglesa de su diario"],["1913","Murray reconstruye el tafl en A History of Chess"],["1932","Se halla el tablero de Ballinderry"]]},"goose":{"title":"El juego de la oca, un regalo para un rey","lead":"Una carrera de dados por una espiral de 63 casillas se regaló a un rey, y luego se jugó en toda Europa.","s":["El juego de la oca es una carrera: se tiran los dados y se avanza por una espiral de 63 casillas hasta la meta del centro. Si caes en una oca, vuelves a avanzar el mismo número. El pozo, la cárcel y la muerte te detienen o te devuelven al inicio.","Se cree que nació en la Italia del siglo XVI. Se dice que Francisco I de Médici, gran duque de Toscana, regaló el juego al rey Felipe II de España entre 1574 y 1587.","En Inglaterra, el impresor londinense John Wolfe registró en 1597 «el nuevo y muy agradable juego de la oca». En los siglos XVII y XVIII fue enormemente popular en toda Europa.","Impreso en papel, se difundió en innumerables versiones con dibujos nuevos: tableros para aprender geografía, de cuentos y fábulas, e incluso publicitarios. Se cree que sirvió de modelo a muchos juegos de carreras posteriores.","Un tablero de doble cara del Museo Metropolitano de Arte tiene la oca por un lado y el ajedrez por el otro. Se cree que lo hicieron artesanos de Guyarat (India) a finales del siglo XVI y podría ser el tablero de la oca más antiguo que se conserva."],"quiz":[["¿Cuántas casillas tiene el juego de la oca?","63","64","100","30"],["¿Quién se dice que regaló el juego al rey de España?","Francisco I de Médici","Napoleón","Isabel I de Inglaterra","Luis XIV"],["¿Qué pasa si caes en una oca?","Vuelves a avanzar el mismo número","Vuelves al inicio","Pierdes un turno","Cambias el sitio con un rival"]],"kf":["Una carrera por una espiral de 63 casillas hasta la meta central, a golpe de dado","Nacido en la Italia del siglo XVI y, según se cuenta, enviado por los Médici al rey de España","Se difundió en láminas impresas, en innumerables versiones con nuevos dibujos y temas"],"more":[{"h":"Una espiral de 63 casillas","p":["En la versión más conocida hay, además de las ocas, algunas casillas especiales. El puente del 6 te lleva al 12; en la posada del 19 pierdes un turno; en el pozo del 31 y la cárcel del 52 quedas atrapado hasta que otro jugador llega a liberarte.","El laberinto del 42 te devuelve al 30, y la muerte del 58 te manda a la salida. Hay que caer en el 63 con la tirada exacta: lo que sobra, se retrocede. El último paso es el más difícil."],"cap":["Las 63 casillas en espiral de fuera hacia dentro. Verde: ocas; azul: el puente; amarillo: esperas (posada, pozo, cárcel); rojo: retrocesos (laberinto, muerte); dorado: la meta"]},{"h":"El enigma del nueve","p":["Las ocas están en el 5, 9, 14, 18…, alternando saltos de 4 y 5. Todos los múltiplos de 9 tienen oca, de modo que un 9 que cae en el 9 te llevaría al 18, al 27… y directo al 63.","Por eso las versiones con dos dados tienen una regla especial: si la primera tirada es 6 y 3, se va al 26; si es 5 y 4, al 53. El 63 es 7×9 y se ha relacionado con los 63 años, considerados entonces la edad más peligrosa de la vida."],"cap":["Las ocas están cada 4 y 5 casillas, así que siempre hay una oca en los múltiplos de 9. Un 9 en la primera tirada saltaría de oca en oca hasta el 63"]},{"h":"La imprenta lo difunde","p":["Los tableros se imprimían con planchas de cobre y tacos de madera y se volvieron baratos. En Francia era el jeu de l’oie; en España, el juego de la oca, donde «de oca a oca y tiro porque me toca» sigue siendo un dicho popular.","No dejaron de aparecer versiones con nuevos dibujos: tableros para aprender geografía e historia, sobre la Revolución francesa o Napoleón, e incluso anuncios de productos. Sobre la misma pista de 63 casillas, cada época dibujó sus propias preocupaciones."],"cap":[]}],"tl":[["s. XVI","Se cree que nace en Italia"],["1574–87","Francisco I de Médici lo habría enviado a Felipe II de España"],["finales s. XVI","En Guyarat (India) se hace un tablero de dos caras: oca por un lado y ajedrez por el otro"],["1597","John Wolfe lo registra para imprimirlo en Londres"],["ss. XVII–XVIII","Furor en toda Europa, con cada vez más versiones temáticas"],["década de 1790","Se hacen tableros sobre la Revolución francesa"],["s. XIX","Se imprime en masa en muchos países como juego infantil"]]},"shogi":{"title":"¿Cuándo nacieron las piezas «en mano» del shogi?","lead":"De toda la familia del ajedrez, solo el shogi deja volver a poner en juego las piezas capturadas como propias. ¿Cuándo y por qué apareció esa regla?","s":["El antepasado indio del ajedrez se extendió al este y al oeste; en Japón se convirtió en el shogi. Las piezas de shogi más antiguas de Japón son 16 halladas a principios de los años noventa en el antiguo recinto de Kōfuku-ji, en Nara. Junto a ellas apareció una etiqueta fechada en 1058 (Tenki 6), así que se cree que las piezas son de la misma época.","Los escritos de entonces también lo mencionan. El Shin Sarugaku-ki, de mediados del siglo XI, lo nombra, y el Nichūreki, que reúne registros de finales del periodo Heian, describe un «shogi Heian» con reyes, generales de oro y de plata, caballos, lanceros y peones.","En los periodos Kamakura y Muromachi surgieron muchas formas mayores, con más piezas. El «shogi pequeño», base del juego actual, añadió la torre y el alfil… y una pieza que ya no existe: el elefante borracho.","Se cree que la regla de reintroducir piezas apareció hacia el siglo XVI. La tradición dice que el emperador Go-Nara mandó quitar el elefante borracho del shogi pequeño, y se cree que las piezas en mano empezaron por entonces.","No está claro por qué surgió. Una explicación: las piezas de ambos bandos son del mismo color y solo se distinguen por hacia dónde apuntan, así que una pieza capturada es fácil de reutilizar. Gracias a ello, en el shogi no se vacía el tablero y las tablas son raras."],"quiz":[["¿Qué fecha tenía la etiqueta hallada con las piezas de Kōfuku-ji?","1058 (Tenki 6)","701 (Taihō 1)","1582 (Tenshō 10)","1868 (Meiji 1)"],["¿Cuándo se cree que apareció la regla de las piezas en mano?","Hacia el siglo XVI","Hacia el siglo VIII","Hacia el siglo XIX","En el siglo XX"],["¿Qué se da como motivo de que fuera fácil reutilizar piezas?","Ambos bandos tienen piezas del mismo color, distinguidas por la dirección","Las piezas eran de oro","El tablero tenía pocas casillas","Las piezas se elegían con dados"]],"kf":["Un pariente del ajedrez nacido en la India que creció en Japón, en un tablero de 9×9","Las piezas más antiguas salieron del antiguo recinto de Kōfuku-ji junto a una tablilla fechada en 1058","Las «piezas en mano» —usar como propias las piezas capturadas— habrían nacido hacia el siglo XVI"],"more":[{"h":"Un solo color, se distinguen por la dirección","p":["Las piezas de ajedrez se pintan de blanco y negro, pero las de shogi son todas del mismo color de la madera: se sabe de quién son por hacia dónde apunta la punta de la pieza de cinco lados. Esa forma es la que permite girar una pieza capturada y soltarla de nuevo en el tablero.","Cada pieza lleva su nombre escrito, y al entrar en el campo enemigo puede darse la vuelta y «promocionar». El peón se convierte en el と de su reverso y se mueve como un general de oro. Que las piezas sean fichas planas con letras y no figuras talladas es algo que el shogi comparte con sus primos de Asia oriental, el xiangqi chino y el janggi coreano."],"cap":["Las piezas de shogi son del mismo color para ambos bandos y se distinguen por hacia dónde apunta la punta. A la derecha, un peón dado la vuelta: «promocionado» (tokin)"]},{"h":"La era de los shogi gigantes","p":["Desde los periodos Kamakura y Muromachi hasta el periodo Edo se crearon shogi cada vez mayores, con más clases de piezas. El chū shogi de 12×12 se jugó mucho durante todo el periodo Edo y aún tiene aficionados.","Los registros van más allá: el dai shogi de 15×15, el tai shogi de 25×25 y el taikyoku shogi, con 804 piezas en un tablero de 36×36. Pero el juego cotidiano era el shō shogi de 9×9, que ganó las piezas en mano y se convirtió en el shogi actual."],"cap":["Tamaños de tablero comparados, dibujados desde una esquina: 9×9 es el shogi actual (40 piezas), 12×12 el chū shogi (92), 15×15 el dai shogi (130), 25×25 el tai shogi (354) y 36×36 el taikyoku shogi (804)"]},{"h":"El shogi en Edo","p":["En el periodo Edo surgieron casas de shogi pagadas por el shogunato; Ōhashi Sōkei se considera el primer maestro. Cada año los mejores jugaban ante el shōgun en las «partidas del castillo», fijadas más tarde para el 17 de noviembre: de ahí viene el actual Día del Shogi.","El shogi también era un placer del pueblo: la estampa de Harunobu muestra a una pareja joven jugando junto a un mosquitero. Y aparecieron colecciones de problemas de tsume-shogi dignas de obras de arte, como el Shōgi Zukō de Itō Kanju (1755)."],"cap":["Estampa a color de Suzuki Harunobu (h. 1767–69): una joven y un joven juegan al shogi junto a un mosquitero"]}],"tl":[["1058","Piezas del antiguo recinto de Kōfuku-ji (halladas con una tablilla del año Tengi 6)"],["med. s. XI","El Shinsarugakuki menciona el shogi"],["inicios de Kamakura","El Nichūreki enumera las piezas del shogi Heian"],["h. s. XVI","Se cree que nacen las piezas en mano"],["1612","Ōhashi Sōkei y otros reciben, según se dice, un estipendio del shogunato"],["1716","Las partidas del castillo se fijan para el 17 de noviembre"],["1755","Shōgi Zukō de Itō Kanju"],["1975","El 17 de noviembre pasa a ser el Día del Shogi"]]},"pachisi":{"title":"Cómo el pachisi se convirtió en el parchís","lead":"Un juego de tablero en cruz de las cortes indias cambió de nombre y llegó a los cuartos de juego de todo el mundo.","s":["En la India existen el chaupar y el pachisi: cuatro jugadores mueven fichas alrededor de un tablero en forma de cruz. El chaupar usa dados alargados (pasa); el pachisi, conchas de cauri. El nombre pachisi significa «veinticinco», la tirada más alta de las conchas.","Hasta los dioses jugaban. Una pintura de finales del siglo XVII muestra al dios Shiva y a su esposa Parvati ante un tablero de chaupar sobre una piel de tigre.","En Fatehpur Sikri, la ciudad del emperador mogol Akbar (siglo XVI), un patio conserva en el suelo un enorme tablero en cruz. Se cuenta que Akbar jugaba usando como fichas a personas vestidas de colores.","En el siglo XIX el juego cruzó los mares. En Estados Unidos se vendió como Parcheesi, marca registrada en 1874. En Gran Bretaña se vendió en la década de 1890 como Ludo —latín, «juego»— y se convirtió en un clásico familiar.","El ludo es más sencillo: un solo dado y un 6 para sacar ficha. Hay parientes con otros nombres en todo el mundo, como el parchís en España o el Mensch ärgere Dich nicht («No te enfades») en Alemania."],"quiz":[["¿Qué significa el nombre «pachisi»?","Veinticinco","El camino del rey","Cruz","Concha de cauri"],["¿Qué ciudad de Akbar conserva un patio con un tablero enorme?","Fatehpur Sikri","El Qutb Minar de Delhi","El Taj Mahal","Ellora"],["¿Qué significa «ludo» en latín?","Juego (yo juego)","Gano","Corro","Lanzo"]],"kf":["Un juego de carreras en un tablero indio en forma de cruz: cuatro jugadores, en dos equipos, dan la vuelta con sus fichas","El nombre significa «25», la tirada más alta de las conchas de cauri","En el siglo XIX cruzó los mares y se extendió por el mundo como Parcheesi, ludo y otros"],"more":[{"h":"La cruz y el camino","p":["El tablero del pachisi es una cruz con cuatro brazos que salen del charkoni central. Cada brazo tiene 3 × 8 casillas, 96 en total. Los tableros solían bordarse en tela, así que podían enrollarse y guardarse.","Las fichas salen del centro, bajan por la columna central de su propio brazo, recorren el tablero una vez en sentido antihorario y vuelven a subir por la columna central. Los jugadores sentados frente a frente son compañeros, y un equipo gana cuando ambos han llevado a casa sus cuatro fichas."],"cap":["Un tablero en cruz (cada brazo de 3 × 8 casillas). La línea azul es el camino de un jugador: baja por el centro de su brazo, da la vuelta completa en sentido antihorario y vuelve a subir por el centro"]},{"h":"Contar los cauris","p":["En el pachisi se lanzan seis conchas de cauri, y el número que cae boca arriba decide el avance. De dos a seis se avanza ese número; pero con una se avanzan 10, y con ninguna, 25.","Con una probabilidad de 1 entre 64, el 25 es la tirada más rara y más alta, y dio nombre al juego. Un 6, un 10 o un 25 dan otra tirada. El chaupar, en cambio, usa tres dados alargados de palo marcados con 1, 2, 5 y 6."],"cap":["De seis cauris, cuántos caen boca arriba (fila superior) y cuánto se avanza (fila inferior). La altura de las barras muestra la frecuencia si cada concha cae de un lado u otro por igual"]},{"h":"Nuevos nombres, nuevos países","p":["A través de los británicos en la India, el juego llegó a Europa y América en el siglo XIX. En Estados Unidos se convirtió en la marca Parcheesi; en Gran Bretaña, el ludo se patentó en 1896, con reglas más sencillas y un solo dado cúbico en lugar de los cauris.","Alemania tuvo en 1914 el Mensch ärgere dich nicht («No te enfades»), y en España se juega al parchís. Nombres y detalles cambian de un país a otro, pero el armazón es el mismo: dar la vuelta a la cruz y volver a casa."],"cap":[]}],"tl":[["s. XVI","Se traza un patio con una cruz gigante en la Fatehpur Sikri de Akbar"],["ss. XVII–XVIII","Las miniaturas indias muestran a menudo gente reunida en torno al chaupar"],["1694–95","Devidasa pinta a Shiva y Parvati jugando al chaupar"],["1874","Parcheesi se registra como marca en EE. UU."],["1896","Se patenta el ludo en Gran Bretaña"],["1914","Sale a la venta en Alemania el Mensch ärgere dich nicht"]]},"go":{"title":"Lo que cuenta un tablero de go de 1.300 años","lead":"El tablero de go del Shōsōin tiene 19 líneas como los de hoy, y 17 marcas de flor, a diferencia de los de hoy.","s":["El go nació en la antigua China. La leyenda dice que el rey sabio Yao lo creó para enseñar a su hijo. El libro de Mencio, anterior a nuestra era, nombra a un maestro del juego, Yi Qiu.","Se cree que el tamaño del tablero cambió con el tiempo: en épocas tempranas también se usaron tableros de 17 líneas, y más tarde se extendió el de 19 líneas actual.","No se sabe cuándo llegó el go a Japón, pero en el periodo Nara ya se jugaba. Las normas para monjes y monjas prohibían la música y los juegos de azar, pero permitían el go y el koto: un trato muy distinto del sugoroku.","El tablero de marquetería del Shōsōin se ha transmitido como un tesoro ligado al emperador Shōmu. Tiene 19 líneas como hoy, pero 17 marcas de flor donde el tablero actual tiene 9 puntos estrella. Sus dos cajones están unidos: al tirar de uno sale también el otro. El Shōsōin guarda además piedras de go de marfil teñido de rojo y azul oscuro, grabadas con aves.","En el periodo Heian, La historia de Genji muestra partidas de go. En el periodo Edo, casas como la Hon’inbō sirvieron al shogunato y el go se convirtió en un arte en que jugadores profesionales medían su habilidad."],"quiz":[["¿Cuántas líneas tiene el tablero de go del Shōsōin?","19","17","13","9"],["¿Qué permitían jugar las normas a monjes y monjas?","El go y el koto","El sugoroku","Juegos de azar","El kemari"],["¿Cuántas marcas de flor tiene el tablero del Shōsōin en lugar de puntos estrella?","17","9","4","25"]],"kf":["Piedras negras y blancas en los puntos donde se cruzan las líneas, para rodear el mayor territorio: un juego nacido en la antigua China","Tras una época de tableros de 17 líneas llegaron las 19; el Shōsōin guarda un tablero de 19 líneas del siglo VIII","En el Japón de Edo, las casas de go servían al shogunato; en el siglo XXI una IA venció al mejor jugador del mundo"],"more":[{"h":"Rodear para capturar, cercar para ganar","p":["En el go, negras y blancas colocan por turnos piedras en los puntos donde se cruzan las líneas. Una vez puesta, la piedra no se mueve. Cuando todos los puntos vacíos junto a una piedra (o un grupo) quedan ocupados por el rival, es capturada y se retira del tablero.","Al final gana quien sume más territorio cercado y piedras capturadas. Las reglas son pocas, pero el tablero es amplio: se ha calculado que en uno de 19 líneas caben unas 10 elevado a 170 posiciones posibles."],"cap":["Cómo se captura. Izquierda: la piedra negra tiene cuatro puntos vacíos al lado (rojo). Centro: las blancas la cercan por tres lados y le queda uno. Derecha: se tapa el último y la piedra negra es capturada"]},{"h":"De 17 líneas a 19","p":["En una tumba de los Han Orientales en Wangdu (Hebei, China) se halló un tablero de go de piedra de 17 líneas. El Clásico del go de Dunhuang, de hacia el siglo VI, describe 361 puntos: un tablero de 19 líneas. Parece que entre ambos el tablero creció.","El tablero del Shōsōin tiene 19 líneas, pero en lugar de los nueve puntos estrella actuales lleva marcas de flor en 17 lugares. Pasar de 289 puntos a 361 hizo el juego mucho más profundo."],"cap":["Los tableros de 17 y 19 líneas comparados por número de puntos. Los nueve puntos negros del tablero actual son los «puntos estrella»"]},{"h":"El go de los inmortales, el go de los maestros","p":["Un cuento chino habla de un leñador que se detuvo en la montaña a mirar a unos inmortales jugar al go y descubrió que habían pasado tantos años que el mango de su hacha se había podrido. El go como pasatiempo de inmortales fue tema favorito de platos y pinturas.","En el Japón de Edo, casas de go como la Hon’inbō recibían un estipendio del shogunato y el go se pulió como un arte. La partida de retirada de Hon’inbō Shūsai, en 1938, inspiró la novela de Kawabata Yasunari El maestro de go. En 2016 la IA AlphaGo venció por 4 a 1 al primer jugador del mundo, Lee Sedol, y asombró al mundo."],"cap":["Plato de laca tallada con inmortales jugando al go (dinastía Ming, periodo Xuande, 1425–36)"]}],"tl":[["h. s. IV a. C.","Mencio nombra al maestro de go Yi Qiu"],["Han Orientales","Se deposita en una tumba de Wangdu un tablero de piedra de 17 líneas"],["h. s. VI","El Clásico del go de Dunhuang describe 19 líneas y 361 puntos"],["s. VIII","El tablero de sándalo con marquetería del Shōsōin"],["1612","Hon’inbō Sansa y otros reciben, según se dice, un estipendio del shogunato"],["1938","Partida de retirada de Hon’inbō Shūsai, luego El maestro de go de Kawabata"],["2016","AlphaGo vence a Lee Sedol por 4 a 1"]]},"draughts":{"title":"Cómo nacieron las damas","lead":"Un juego de tablero árabe, el tablero de ajedrez y la reina del ajedrez: se cree que las damas nacieron del encuentro de los tres.","s":["Se considera antepasado de las damas el alquerque, jugado sobre una cuadrícula de 5×5 puntos unidos por líneas. En árabe se llamaba qirq y aparece en el Libro de las canciones del siglo X. Los moros lo llevaron a España, y sus reglas figuran en el Libro de los juegos que mandó hacer Alfonso X de Castilla en el siglo XIII.","Hacia el siglo XII, probablemente en el sur de Francia, se empezaron a mover las piezas del alquerque sobre un tablero de ajedrez. Así nació el fierges. Las piezas tomaron el nombre de la reina del ajedrez de entonces, la fers.","La coronación —la pieza que llega al fondo se vuelve más fuerte— ya aparece en una crónica de mediados del siglo XIII. Quizá se tomó del peón del ajedrez que se convierte en reina.","El gran cambio llegó en Francia hacia 1535: se añadió la captura obligatoria —si puedes comer, debes hacerlo— y el juego se llamó jeu forcé, «juego forzado». Las damas inglesas y las checkers estadounidenses descienden de él.","El juego antiguo sin captura obligatoria sobrevivió como «juego amable de damas» y más tarde dio lugar a las damas internacionales de 10×10. De un mismo antepasado brotaron muchos «juegos de damas», de reinas."],"quiz":[["¿Qué juego se considera antepasado de las damas?","El alquerque","El senet","El liubo","El mancala"],["¿Cuándo y dónde se añadió la captura obligatoria?","En Francia, hacia 1535","En Bagdad, en el siglo X","En Estados Unidos, en 1900","En Japón, en el siglo VIII"],["¿De qué tomaron su nombre las piezas del fierges?","De la reina del ajedrez (fers)","Del rey del ajedrez","De los dados","Del caballo"]],"kf":["Nació cuando las piezas del juego árabe del alquerque pasaron a un tablero de ajedrez","Las piezas avanzan en diagonal y capturan saltando; al llegar a la última fila, coronan","Hacia 1535 llegó la captura obligatoria, y en 2007 el juego quedó resuelto"],"more":[{"h":"De puntos y líneas al tablero de ajedrez","p":["El tablero de alquerque son 25 puntos en una cuadrícula de 5 × 5 unidos por líneas. Cada bando coloca 12 piezas y se empieza desde el único punto vacío del centro. Las piezas avanzan por las líneas y capturan saltando sobre una enemiga contigua.","Al pasar las piezas a un tablero de ajedrez, solo se usaron las casillas de un color. Un tablero de 8 × 8 tiene 32 casillas oscuras; llenando las tres primeras filas de cada lado salen 12 piezas por bando: las mismas que en el alquerque."],"cap":["El tablero de alquerque y su posición inicial: 5 × 5 puntos unidos por líneas rectas y diagonales, 12 piezas por bando y solo el centro vacío"]},{"h":"Saltar para capturar, coronar para crecer","p":["Las piezas avanzan una casilla en diagonal y capturan saltando sobre una enemiga contigua si la casilla de detrás está libre. Si después pueden capturar otra, siguen saltando. En las damas actuales, si se puede capturar, hay que hacerlo.","La pieza que llega a la última fila corona —se le pone otra encima— y, como dama, puede ir también hacia atrás. En el juego internacional de 10 × 10, la dama recorre cualquier distancia en diagonal, lo que transforma el final."],"cap":["Captura y coronación. La pieza roja salta dos blancas seguidas (×) y después llega a la última fila para convertirse en dama, con dos piezas apiladas"]},{"h":"Un juego resuelto y una familia que crece","p":["En Canadá, Jonathan Schaeffer y su equipo crearon el programa de damas Chinook. En 1992 se enfrentó a Marion Tinsley, que en más de 40 años apenas había perdido partidas, y ganó Tinsley. El equipo siguió calculando y en 2007 demostró que, si ambos juegan perfectamente, las damas acaban en tablas.","Mientras tanto, la familia del mismo antepasado sigue viva en todo el mundo: las damas internacionales de 10 × 10, las shashki rusas, la dama turca de movimientos ortogonales, las damas canadienses de 12 × 12… y en cada país se siguen jugando torneos."],"cap":[]}],"tl":[["s. X","El Libro de las canciones nombra el qirq (alquerque)"],["h. s. XII","Nace el fierges, probablemente en el sur de Francia"],["1283","El Libro de los juegos de Alfonso X describe el alquerque"],["h. 1535","En Francia se añade la captura obligatoria"],["1547","Torquemada publica en España el primer libro de damas"],["s. XVIII","El tablero de 10 × 10 se extiende por Francia y los Países Bajos"],["1992","Tinsley vence al programa Chinook"],["2007","Se demuestra que las damas son tablas con juego perfecto"]]},"reversi":{"title":"Reversi y Othello: ¿quién los inventó?","lead":"Un juego de encerrar y voltear fichas blancas y negras, y dos hombres en la Inglaterra del siglo XIX que se lo disputaron.","s":["En el Londres de la década de 1880, dos ingleses, Lewis Waterman y John W. Mollett, afirmaban cada uno ser el inventor del juego y llamaban farsante al otro.","El juego de Mollett, Annexation, usaba un tablero en forma de cruz. El Reversi de Waterman usaba un tablero normal de 8×8, y es su forma la que ha llegado hasta hoy. La disputa por el nombre llegó incluso a los tribunales.","El reversi se extendió por Europa; en 1893 la firma alemana Ravensburger lo lanzó como uno de sus primeros productos. En Japón se describió en libros de la era Meiji y también se llamó genpei-go.","Su popularidad no duró. En 1971, Goro Hasegawa lanzó «Othello», fijando la apertura con las cuatro primeras fichas cruzadas en el centro, y se convirtió en una fiebre en Japón.","Se dice que el nombre viene de la obra de Shakespeare: el general negro Otelo y su esposa blanca Desdémona evocan las fichas negras y blancas. Las reglas de los torneos actuales son las de Othello."],"quiz":[["¿Cuándo y dónde vivían los dos hombres que se disputaron el reversi?","En la Inglaterra del siglo XIX","En la Francia del siglo XVIII","En el Japón del siglo XX","En la Italia del siglo XVI"],["¿Qué forma tenía el tablero de Annexation de Mollett?","De cruz","Redonda","Triangular","Cuadrada de 8×8"],["¿Quién lanzó Othello en 1971?","Goro Hasegawa","Hon’inbō Shūsaku","Lewis Waterman","Ravensburger"]],"kf":["Encierra las fichas rivales entre las tuyas para darles la vuelta; al final gana quien tenga más","En el Londres de la década de 1880, dos ingleses se disputaron su invención","En los años setenta arrasó en Japón como Othello, y en 2023 se demostró que es tablas con juego perfecto"],"more":[{"h":"Encerrar y voltear","p":["Solo se puede poner una ficha donde encierre una línea de fichas rivales entre ella y otra propia. Las líneas van en ocho direcciones —horizontal, vertical y diagonal— y una jugada puede encerrar varias a la vez. Todas las fichas encerradas se voltean a tu color.","Si no tienes jugada, pasas, y la partida termina cuando ninguno puede mover. Las fichas de las esquinas nunca pueden encerrarse, así que tomar una esquina es una gran ventaja. Los buenos jugadores se fijan menos en cuántas fichas tienen ahora que en reducir dónde puede jugar el rival."],"cap":["Cómo se voltean las fichas. Una negra colocada en la casilla del círculo rojo encierra blancas en tres direcciones —horizontal, vertical y diagonal— y las siete de borde dorado pasan a negras"]},{"h":"Las cuatro primeras fichas","p":["En el reversi antiguo, los dos jugadores ponían por turnos las cuatro primeras fichas en las cuatro casillas centrales, así que la apertura podía quedar lado a lado o cruzada.","El Othello fijó el inicio cruzado. Desde la primera jugada ambos colores son fáciles de encerrar y la lucha empieza enseguida. Los campeonatos mundiales actuales parten de esta posición."],"cap":["Las cuatro primeras fichas. Izquierda: una forma en que podía empezar el reversi antiguo, con los mismos colores lado a lado. Derecha: el inicio cruzado que fijó el Othello"]},{"h":"Humanos y computadoras","p":["El Othello pasó de Japón al mundo, y en 1977 se celebró en Tokio el primer Campeonato Mundial. Las reglas son sencillas, así que decide la profundidad del cálculo: los mejores ven decenas de jugadas por delante.","En 1997 el programa Logistello jugó seis partidas contra el campeón del mundo Takeshi Murakami y las ganó todas. En 2023 se demostró mediante cálculo que el Othello de 8 × 8 termina en tablas si ambos juegan perfectamente."],"cap":[]}],"tl":[["década de 1880","Waterman y Mollett se disputan la invención en Londres"],["1893","Ravensburger lanza el Reversi en Alemania"],["era Meiji","Libros japoneses lo presentan como genpei-go"],["1973","Salen a la venta en Japón los juegos de Othello"],["1977","Primer Campeonato Mundial de Othello, en Tokio"],["1997","Logistello vence 6–0 al campeón Takeshi Murakami"],["2023","Se demuestra que el Othello de 8 × 8 es tablas con juego perfecto"]]},"mancala":{"title":"¿Dónde nació el mancala?","lead":"Un juego de sembrar piedras de hoyo en hoyo, jugado en África y Asia con cientos de nombres.","s":["Mancala es el nombre de una familia de juegos en los que se toman piedras o semillas de un hoyo y se siembran una a una en los siguientes. Se dice que la palabra viene del árabe naqala, «mover».","Los nombres y las reglas cambian de un lugar a otro —oware en África occidental, bao en África oriental, mangala en Turquía, congkak en el sudeste asiático y cientos más—, con dos filas o cuatro y cualquier número de hoyos.","Se suele decir que es antiquísimo, pero las pruebas firmes son más recientes de lo que se piensa. Los tableros más antiguos con fecha segura son, por ahora, tableros de cerámica y piedra de hacia los siglos VI–VII hallados en yacimientos del antiguo reino de Aksum, en Matara y Yeha (Eritrea y Etiopía).","Se han propuesto ejemplos más antiguos, pero no es seguro que esas hileras de hoyos fueran de mancala, y los especialistas discrepan. Una opinión destacada es que el juego se extendió desde Aksum a Arabia y al interior de África.","Las descripciones completas de cómo se jugaba aparecen hacia el siglo XVII. En el Atlas puedes jugar al mancala con ocho reglamentos, entre ellos el oware y la mangala."],"quiz":[["¿Qué significa la palabra árabe de la que viene «mancala»?","Mover","Semilla","Hoyo","Rey"],["¿Dónde se hallaron los tableros de mancala más antiguos con fecha segura?","En yacimientos del antiguo reino de Aksum (Etiopía y Eritrea)","En el Coliseo de Roma","En la Gran Muralla china","En Stonehenge"],["¿Qué mancala se juega en África occidental?","El oware","El liubo","El tafl","El pachisi"]],"kf":["Una familia de juegos de «siembra»: se sacan las semillas de un hoyo y se dejan una a una en los siguientes","Los tableros más antiguos bien fechados proceden del antiguo reino de Aksum, hacia los siglos VI–VII","Dos filas o cuatro, con o sin almacenes: el tablero y las reglas cambian de una región a otra"],"more":[{"h":"Sembrar","p":["En el mancala se elige un hoyo del propio lado, se sacan todas sus semillas y se dejan una a una en los hoyos siguientes. Este movimiento, como esparcir semillas en un campo, se llama sembrar.","El oware, de África occidental, empieza con 48 semillas, cuatro en cada uno de 12 hoyos. Si la última semilla deja dos o tres en un hoyo rival, se capturan. Saber dónde terminará una siembra —contar por adelantado— lo es todo. El oware cruzó el Atlántico y también se juega en el Caribe."],"cap":["La siembra en el oware. Las tres semillas del hoyo del anillo dorado se reparten una a una en sentido antihorario; la última deja exactamente 3 en un hoyo rival, que se capturan (anillo rojo)"]},{"h":"Dos filas y cuatro","p":["Los tableros de mancala se dividen en general en dos tipos: de dos y de cuatro filas. Los de dos filas abundan en África occidental y Asia; los de cuatro se extienden de África oriental al sur del continente. El bao de Tanzania tiene 4 filas de 8 hoyos, y su nombre significa simplemente «tablero» en suajili.","Algunos, como el congkak y el sungka del Sudeste Asiático, tienen en cada extremo un hoyo grande —un almacén— para las semillas capturadas. El kalah, nacido en Estados Unidos en el siglo XX, es un juego de dos filas con almacenes, y en 2000 se calculó que el kalah con seis hoyos y cuatro semillas en cada uno lo gana siempre el primer jugador."],"cap":["Ejemplos de tableros de mancala: 2 filas de 6 (oware y otros), 2 filas de 7 con un almacén en cada extremo (congkak del Sudeste Asiático y otros), 4 filas de 8 (bao de África oriental y otros)"]},{"h":"Quienes lo pusieron por escrito","p":["Se suele decir que el primer erudito europeo que describió el mancala con detalle fue el inglés Thomas Hyde. En De Ludis Orientalibus (1694) dio su nombre árabe y explicó cómo se jugaba.","En 1836, Edward W. Lane, al describir la vida cotidiana de El Cairo, anotó el «mankalah» que se jugaba en los cafés. Hoy los investigadores han reunido juegos de todas partes, y las reglas registradas se cuentan por cientos."],"cap":[]}],"tl":[["ss. VI–VII","Los tableros más antiguos bien fechados, en yacimientos de Aksum"],["1694","Thomas Hyde describe el mancala en De Ludis Orientalibus"],["ss. XVIII–XIX","El oware y otros cruzan el Atlántico hasta el Caribe"],["1836","E. W. Lane anota el mankalah de El Cairo"],["mediados del s. XX","Sale a la venta en EE. UU. el kalah, de dos filas con almacenes"],["2000","Se calcula que el kalah de seis hoyos y cuatro semillas lo gana el primer jugador"]]},"morris":{"title":"El molino está en todas partes","lead":"El tejado de un templo, un barco vikingo, el banco de piedra de una catedral: sus líneas se tallaron dondequiera que la gente se sentaba junta.","s":["En el molino (nine men’s morris), cada jugador coloca nueve fichas en los 24 puntos de tres cuadrados anidados; tres en línea, un «molino», captura una ficha rival. El nombre inglés «morris» no tiene que ver con la danza: vendría del latín merellus, ficha o tanto.","Un tablero grabado en una losa del tejado del templo de Kurna, en Egipto, suele presentarse como el más antiguo, de hacia 1400 a. C. Pero el estudioso Friedrich Berger señaló cruces coptas entre esos mismos grabados y concluyó que no pueden fecharse. Los ejemplos seguros empiezan en época romana.","En el barco de Gokstad, de Noruega, de hacia el año 900, hay un tablero tallado en una tabla de la cubierta. En Inglaterra se conservan tableros en los bancos de piedra de claustros de catedrales como Canterbury y Salisbury.","El Libro de los juegos de Alfonso X, de 1283, lo muestra incluso jugado con dados. Shakespeare, en El sueño de una noche de verano, cuenta que las lluvias dejaron el tablero «lleno de barro»: un tablero cavado en el prado del pueblo.","En 1996 el alemán Ralph Gasser examinó con un ordenador todas las posiciones y demostró que, si ambos juegan perfecto, la partida acaba en tablas. Entre dos personas sigue siendo un juego excelente."],"quiz":[["¿De dónde vendría el nombre «morris»?","Del latín «ficha»","De una danza inglesa","De un nombre de persona","Del nombre de un barco"],["¿Qué señalaron los estudiosos sobre los tableros de Kurna?","Que no pueden fecharse","Que son de oro","Que vinieron de China","Que eran de un emperador"],["¿Qué demostró un ordenador en 1996?","Con juego perfecto, tablas","Gana siempre quien empieza","Gana siempre el segundo","Bastan ocho fichas"]],"kf":["Nueve fichas por jugador en los 24 puntos de tres cuadrados anidados; tres en línea capturan una ficha rival","Desde época romana, su tablero se grabó allí donde la gente se reunía: cubiertas de barcos, bancos de catedrales","En 1996 se examinaron por ordenador todas las posiciones: con juego perfecto, tablas"],"more":[{"h":"Colocar, mover, volar","p":["La partida tiene tres fases. Primero los jugadores colocan por turnos sus nueve fichas en puntos vacíos. Cuando todas están puestas, mueven una ficha cada vez por una línea hasta un punto vecino vacío.","Tres fichas propias en línea forman un «molino» y permiten retirar una ficha rival del tablero. Una regla habitual permite al jugador que queda con tres fichas «volar» a cualquier punto vacío. Pierde quien se queda con dos fichas o no puede mover."],"cap":["Un tablero de molino. Las blancas han formado un molino en el lado exterior (dorado) y pueden quitar una ficha negra (cruz roja)"]},{"h":"De tres fichas a doce","p":["La familia se nombra por su número de fichas. El molino de tres, con tres fichas cada uno, es un tablero pequeño cercano al tres en raya. El de seis usa un tablero de dos cuadrados anidados.","El de doce añade líneas diagonales al tablero del de nueve. En Sudáfrica se llama morabaraba; se dice que los pastorcillos lo trazaban en el suelo, y hoy tiene sus propios torneos."],"cap":["Tableros comparados. El número indica las fichas de cada jugador: molino de tres, de seis, de nueve y de doce"]},{"h":"Un campeón de ajedrez y una computadora","p":["El campeón mundial de ajedrez Emanuel Lasker fue uno de los que se apasionaron por el juego. En su libro Brettspiele der Völker (1931) propuso una versión con diez fichas por jugador, en la que se puede mover antes de haber colocado todas.","En 1996, Ralph Gasser, en Suiza, combinó tablas completas de finales con una búsqueda desde la apertura y demostró que el molino de nueve es tablas si ambos juegan perfectamente. El tablero tiene solo 24 puntos, pero las posiciones se cuentan por miles de millones."],"cap":[]}],"tl":[["época romana","Se graban tableros en piedra por todo el imperio (los primeros ejemplos seguros)"],["h. 900","Se graba un tablero en una tabla de la cubierta del barco de Gokstad (Noruega)"],["1283","El Libro de los juegos de Alfonso X ilustra el molino"],["Edad Media","Se graban tableros en bancos de claustros de catedrales inglesas"],["década de 1590","El sueño de una noche de verano, de Shakespeare, menciona un tablero lleno de barro"],["1931","Lasker propone una nueva versión en Brettspiele der Völker"],["1996","Gasser demuestra que con juego perfecto es tablas"]]},"patolli":{"title":"El patolli, la carrera de frijoles azteca","lead":"Un tablero en cruz y frijoles como dados: un juego de apuestas tan acaloradas que los españoles lo prohibieron.","s":["El patolli era un juego de carreras de los aztecas de México. Su nombre significa frijoles: se lanzaban cinco frijoles rojos marcados o perforados por una cara y se avanzaba según las marcas visibles, por un recorrido en cruz pintado en una estera o en el suelo.","Diego Durán, que registró la región en el siglo XVI, escribió que los jugadores quemaban incienso y rezaban a los frijoles antes de tirar, e invocaban a Macuilxóchitl, dios de los juegos, para ganar.","Los nobles apostaban joyas, mantas y hasta a sí mismos; algunos que perdían quedaban como esclavos. También se cuenta que el emperador Moctezuma miraba jugar a sus nobles.","Los frailes españoles, que rechazaban las apuestas y los rezos a los antiguos dioses, prohibieron el patolli, rompieron las esteras y quemaron los frijoles, por lo que quedan pocos juegos. Aun así, se han hallado tableros grabados en suelos de piedra y rocas en Teotihuacan y en sitios mayas, y en 1977 entre petroglifos de Jalisco.","Un tablero en cruz con piezas que lo recorren se parece mucho al pachisi de la India. En 1878 el inglés E. B. Tylor defendió un origen asiático; hoy la mayoría cree que surgieron por separado."],"quiz":[["¿Qué se lanzaba en el patolli en lugar de dados?","Frijoles marcados","Huesos de animal","Conchas","Palos de madera"],["Según los registros, ¿por qué se prohibió el patolli?","Por las apuestas y los rezos a los antiguos dioses","El tablero era muy grande","Los frijoles eran caros","Perdió el rey"],["¿A qué juego se parece mucho el tablero del patolli?","Al pachisi","Al go","A las damas","Al mancala"]],"kf":["Un juego de carreras azteca: se lanzan cinco frijoles marcados y se mueven fichas por un tablero en cruz","Unido a las apuestas y a las oraciones a los dioses, lo prohibieron los frailes españoles","Se parece muchísimo al pachisi de la India, pero se cree que ambos nacieron por separado"],"more":[{"h":"Un camino en cruz de 52 casillas","p":["Un tablero de patolli es un camino en forma de cruz pintado sobre tela, una estera o un piso de piedra. Las reconstrucciones suelen dar a cada brazo dos carriles de casillas que, con las cuatro del centro, suman 52.","Cincuenta y dos es también el número de años de la rueda calendárica azteca, y algunos investigadores ven en el tablero una imagen del calendario o del paso del tiempo. Los jugadores daban una vuelta completa con sus fichas, y ganaba el primero en volver."],"cap":["Un tablero de patolli como suele reconstruirse: cuatro brazos con dos carriles de seis casillas, más cuatro centrales, 52 en total. Las casillas rojas del extremo de cada brazo serían especiales"]},{"h":"Cinco frijoles","p":["En lugar de dados se lanzaban cinco frijoles marcados en una cara con un agujero o una señal, y se avanzaba tantas casillas como marcas salieran. Las cinco marcas salen solo una vez de cada 32.","Se dice que antes de lanzar se les hablaba a los frijoles y se invocaba a Macuilxóchitl, dios de los juegos. El Códice Magliabechiano, del siglo XVI, muestra a varias personas en torno a un patolli bajo la mirada del dios."],"cap":["De cinco frijoles, cuántos caen con la cara marcada hacia arriba (0–5) y con qué frecuencia (de cada 32), si cada uno cae de un lado u otro por igual"]},{"h":"El doble del pachisi","p":["Fichas que rodean un tablero en cruz y avances según cuántas piezas lanzadas caen boca arriba: el patolli y el pachisi o el chaupar de la India se parecen asombrosamente. En 1878 el antropólogo británico Tylor sostuvo que no era casualidad, sino señal de que el juego había llegado de Asia.","Pero no se ha hallado ninguna prueba de semejante cruce de océanos. Hoy la mayoría piensa que en lugares distintos la gente llegó por su cuenta a las mismas ideas: un camino que da la vuelta y piezas para lanzar."],"cap":["Pintura del chaupar en la India (1694–95): fichas que recorren un tablero en cruz, como en el patolli"]}],"tl":[["época de Teotihuacan","Se graban tableros en cruz en pisos de piedra"],["1519–21","España conquista a los aztecas"],["s. XVI","El Códice Magliabechiano muestra el patolli y a Macuilxóchitl"],["h. 1577","Sahagún registra el patolli en el Códice Florentino"],["h. 1581","Durán describe las oraciones y las apuestas"],["1878","Tylor defiende un origen asiático"],["1977","Se halla un tablero entre arte rupestre de Jalisco"]]},"xiangqi":{"title":"El río y el cañón del xiangqi","lead":"Un «río» en medio y un cañón que salta para capturar: ¿cuándo tomó su forma actual el ajedrez chino?","s":["El xiangqi es el ajedrez chino, que se juega sobre los puntos de una cuadrícula de 9×10. Sus piezas son discos con caracteres y se mueven sobre las líneas, no dentro de casillas como en el ajedrez.","Una pista temprana es el Xuanguai lu, libro de relatos extraños del ministro Tang Niu Sengru (779–847). El sueño de un hombre sobre un ejército diminuto menciona un caballo celestial, un general, carros e infantería, con indicios de una catapulta. Pero el tablero y los movimientos no son los de hoy.","La forma actual —el tablero de 9×10, el río y el cañón— aparece en registros de la dinastía Song (960–1279). En una tumba Song del Norte en Luoyang se ha hallado un juego completo de piezas.","El río suele llevar escrito «Río Chu, frontera Han», por la línea entre el Chu de Xiang Yu y el Han de Liu Bang en su guerra del siglo III a. C. El general no puede salir de su palacio, y los dos generales nunca pueden mirarse sin nada en medio.","El cañón solo captura saltando exactamente una pieza. El xiangqi es muy querido en Vietnam como cờ tướng, y en Corea dio lugar a su pariente cercano, el janggi. En el Atlas puedes jugar a ambos."],"quiz":[["¿Dónde se mueven las piezas del xiangqi?","En los puntos de las líneas","Dentro de casillas","Alrededor de un círculo","En hexágonos"],["¿En qué dinastía aparece en los registros el xiangqi actual?","Song","Han","Ming","Qing"],["¿Cómo captura el cañón?","Saltando una pieza","Un paso recto","Dos pasos en diagonal","Solo tras cruzar el río"]],"kf":["El ajedrez chino: piezas redondas con caracteres luchan sobre los puntos de una retícula de 9 × 10 líneas","Un «río» cruza el centro y cada bando tiene un «palacio» para su general; cada pieza tiene su terreno","Tomó su forma actual en la dinastía Song y aún lo juegan decenas de millones en China y Vietnam"],"more":[{"h":"Un tablero con río y palacios","p":["Cada bando tiene 16 piezas: un general, 2 consejeros, 2 elefantes, 2 caballos, 2 carros, 2 cañones y 5 soldados. Rojas y negras escriben algunas de las mismas piezas con caracteres algo distintos.","El general y los consejeros no pueden salir del palacio, y los elefantes no pueden cruzar el río. Los soldados solo avanzan hasta cruzar el río; después también pueden moverse de lado. Un caballo no puede saltar si hay una pieza justo a su lado en la dirección en que quiere ir. El propio tablero define lo que puede hacer cada pieza."],"cap":["Posición inicial del xiangqi. Negras arriba, rojas abajo. Los caracteres 楚河 漢界 señalan el río; las zonas de 3 × 3 con diagonales son los palacios"]},{"h":"El cañón que salta","p":["El cañón se mueve normalmente como el carro, cualquier distancia por una línea. Pero para capturar debe saltar exactamente una pieza intermedia, de cualquier color, llamada pantalla.","Usar piezas como pantalla crea tácticas que no existen en ningún otro juego. Llevar un cañón a la columna central al empezar, el «cañón central», sigue siendo una de las aperturas más populares."],"cap":["Cómo captura el cañón: el cañón rojo salta exactamente una pieza intermedia —el caballo negro— para tomar el carro negro de más allá"]},{"h":"Partidas y maestros","p":["En la dinastía Ming se publicaron muchos libros que reunían buenas partidas y problemas. El Shiqing yaqu (1570) y el Juzhong mi (1632) son clásicos que aún se estudian.","En el siglo XX, Hu Ronghua ganó diez veces seguidas el campeonato nacional de China, y en 1993 se fundó la Federación Mundial de Xiangqi, que trajo torneos internacionales. En los parques de China y Vietnam, cada día se forman corros alrededor del tablero."],"cap":[]}],"tl":[["s. IX","El Xuanguai lu de Niu Sengru menciona generales, carros y caballos"],["Song (960–1279)","Aparece en los registros la forma actual, con tablero de 9 × 10, río y cañón"],["Song del Norte","Se deposita un juego completo de piezas en una tumba de Luoyang"],["1570","La colección de partidas Shiqing yaqu"],["1632","La colección de partidas Juzhong mi"],["décadas de 1960–70","Hu Ronghua gana diez títulos nacionales seguidos"],["1993","Se funda la Federación Mundial de Xiangqi"]]},"backgammon":{"title":"¿Tiene el backgammon 5.000 años?","lead":"El tablero llamado «el backgammon más antiguo» y los verdaderos antepasados del juego: de una corte persa a los clubes de Nueva York.","s":["La «Ciudad Quemada» de Shahr-e Sukhteh, en Irán, dio un tablero de unos 5.000 años con 60 piezas y dados, a menudo llamado el backgammon más antiguo. Pero sus casillas las forman las espirales de una serpiente tallada, unas veinte: una forma distinta del juego actual.","El antepasado directo probable del backgammon es el nard persa, surgido entre los siglos III y VI. Un relato en persa medio, escrito entre los siglos VII y IX, cuenta que el ministro Bozorgmehr, tras resolver el enigma del ajedrez enviado desde la India, inventó el nard como respuesta.","Roma tenía su propio juego de tablero con tres dados, la tabula: la desafortunada partida del emperador Zenón del relato 3. Esta familia de «tablas» se extendió por Europa y dio muchos parientes, como el tric-trac francés.","El nombre «backgammon» aparece en la Inglaterra del siglo XVII, y en 1743 Edmond Hoyle publicó sus reglas y su estrategia.","El último gran invento, el cubo doblador, habría nacido en clubes de Nueva York en la década de 1920. Al poder doblar la apuesta a mitad de partida, convirtió el backgammon en un juego profundo de saber cuándo apretar."],"quiz":[["¿Qué forma tiene el tablero de Shahr-e Sukhteh?","Casillas hechas por las espirales de una serpiente","La misma que el backgammon actual","Un disco redondo","Una cruz"],["Según el relato, ¿quién inventó el nard?","El ministro Bozorgmehr","El emperador Zenón","Edmond Hoyle","Alfonso X"],["¿Qué habría nacido en Nueva York en los años veinte?","El cubo doblador","Los dos dados","Los 24 triángulos","Las quince fichas"]],"kf":["Quince fichas por bando corren sobre 24 puntas triangulares según dos dados; gana quien saque antes todas","Sus antepasados directos son el nard persa y la tabula romana y otros juegos de «tablas»","El cubo doblador y las computadoras le dieron nueva profundidad en el siglo XX"],"more":[{"h":"Quince fichas y 24 puntas","p":["El tablero tiene 24 triángulos largos, o puntas, y cada jugador tiene 15 fichas. Se tiran dos dados y se mueve una ficha por cada número, o una sola por ambos. Un doble permite usar el número cuatro veces.","Caer sobre una ficha rival solitaria la «come» y la manda a la barra del centro; debe volver a entrar por la casa del rival. Cuando las quince fichas propias están en casa, se empiezan a sacar del tablero, y gana quien termine primero."],"cap":["Posición inicial del backgammon. Las blancas van de la 24 a la 1 (en sentido antihorario); las puntas 1–6, abajo a la derecha, son su casa. Las negras van al revés"]},{"h":"Cuanto más cerca, más fácil acertar","p":["Poder comer una ficha solitaria depende mucho de la distancia. A seis puntas aciertan 17 de las 36 tiradas; a siete, solo 6.","Conocer estas cifras dice dónde está en peligro una ficha. Al empezar, cada jugador necesita 167 puntos de dado para llevar todas sus fichas a casa y sacarlas; los buenos jugadores cuentan este «pip count» para juzgar quién va por delante."],"cap":["Cuántas de las 36 tiradas de dos dados pueden comer una ficha solitaria a 1–12 puntas de distancia (sin nada que estorbe)"]},{"h":"De los clubes a los campeonatos mundiales","p":["En 1743 Edmond Hoyle publicó en Inglaterra un libro de reglas y estrategia. En la Gran Bretaña del siglo XIX el juego gustaba tanto que se pintaba en los muebles, y en los clubes de Nueva York de los años veinte nació el cubo doblador.","En 1964 se celebró un campeonato mundial en las Bahamas, y en los setenta el juego vivió un auge. En 1979 el programa de Hans Berliner venció al campeón mundial Luigi Villa, y hacia 1992 TD-Gammon, que aprendía jugando contra sí mismo, alcanzó una fuerza cercana a la de los mejores humanos."],"cap":["Un mueble pintado con dos jugadores de backgammon (Londres, 1861), de los primeros de Morris, Marshall, Faulkner & Co."]}],"tl":[["h. 3000 a. C.","Se entierran en Shahr-e Sukhteh un tablero de serpiente enroscada, fichas y dados"],["h. ss. III–VI","Aparece el nard en Persia"],["1743","Hoyle publica su libro sobre el backgammon"],["década de 1920","Nace en Nueva York el cubo doblador"],["1964","Campeonato mundial en las Bahamas"],["1979","El programa de Berliner vence al campeón mundial"],["h. 1992","Aparece TD-Gammon, que aprende jugando contra sí mismo"]]},"hex":{"title":"Hex, inventado dos veces","lead":"Un poeta danés y un joven genio estadounidense idearon el mismo juego sin saber el uno del otro.","s":["En el Hex, los jugadores colocan piedras por turnos en un rombo de hexágonos; gana quien une sus dos lados opuestos. Eso es todo.","El primero en idearlo fue el matemático y poeta danés Piet Hein. En 1942 lo presentó en el Instituto Niels Bohr de Copenhague; el 26 de diciembre de ese año el periódico Politiken lo publicó como «Polygon», y se vendió en blocs de 50 hojas.","En 1943 Hein tuvo que salir de Dinamarca y el juego se desvaneció. Unos años después, en 1948–49, John Nash, estudiante de posgrado en Princeton, inventó el mismo juego de forma totalmente independiente; sus compañeros lo llamaban «Nash».","En 1952 Parker Brothers lo vendió como «Hex», y en 1957 Martin Gardner lo presentó en su columna de Scientific American, dándolo a conocer al mundo.","El Hex nunca acaba en tablas. Y Nash demostró que el primer jugador siempre tiene una estrategia ganadora, sin mostrar cuál es. En tableros grandes, esa forma de ganar aún se desconoce."],"quiz":[["¿Cómo se gana al Hex?","Uniendo tus dos lados","Capturando todas las piedras","Rodeando al rey","Haciendo cinco en línea"],["¿Cómo se llamaba el juego de Hein en el periódico danés?","Polygon","Nash","Con-tac-tix","Othello"],["¿Qué demostró Nash?","Que el primero siempre puede ganar","Que el segundo siempre gana","Que siempre hay tablas","Las jugadas ganadoras exactas"]],"kf":["Por turnos se colocan piedras en casillas hexagonales; gana quien une sus dos lados opuestos","Lo inventaron por separado Piet Hein en Dinamarca (1942) y John Nash en EE. UU. (1948–49)","No hay empates y está demostrado que gana el primer jugador, pero en tableros grandes nadie sabe cómo"],"more":[{"h":"Un juego de unir","p":["El tablero es un rombo de casillas hexagonales; el tamaño oficial es 11 × 11. Rojo defiende los lados superior e inferior, y azul los laterales; colocan por turnos una piedra cada vez. Las piedras nunca se mueven ni se capturan.","Cuando el tablero se llena, siempre hay un bando conectado. Los hexágonos nunca se tocan solo por un vértice, así que no se puede colar uno entre las piedras del rival. En 1979 el matemático David Gale demostró que esta propiedad de «sin empates» equivale a un célebre resultado matemático, el teorema del punto fijo de Brouwer."],"cap":["Un tablero de hex de 7 × 7. Rojo gana uniendo arriba y abajo; azul, izquierda y derecha. Las piedras rojas de borde dorado ya han unido arriba con abajo"]},{"h":"Puentes y escaleras","p":["Una herramienta favorita de los buenos jugadores es el puente. Si colocas una piedra no al lado de la anterior sino una casilla más allá, ambas comparten dos casillas vacías vecinas. Si el rival tapa una, tomas la otra: en la práctica ya están unidas.","Junto a los bordes se conocen muchas formas fijas, como las «escaleras» de piedras que avanzan a lo largo del lado. Como el primer jugador tiene demasiada ventaja, suele usarse la regla del intercambio: tras la primera jugada, el segundo puede quedarse esa piedra como propia."],"cap":["El «puente». Las dos piedras rojas pueden unirse por cualquiera de las dos casillas vacías de en medio (círculos punteados). Si azul ocupa una, rojo ocupa la otra"]},{"h":"Un juego de matemáticos","p":["Nash demostró que gana el primer jugador con un argumento de «robo de estrategia»: si el segundo tuviera una estrategia ganadora, el primero podría apropiársela, lo cual es contradictorio. Es una prueba curiosa que no muestra ninguna jugada ganadora concreta.","En los años cincuenta, Claude Shannon, padre de la teoría de la información, construyó una máquina que jugaba al hex con un circuito eléctrico. En la década de 2010 las computadoras resolvieron todos los tableros hasta 9 × 9, pero el oficial de 11 × 11 sigue sin resolver."],"cap":[]}],"tl":[["1942","Hein publica «Polygon» en un periódico danés"],["1948–49","Nash, en Princeton, idea el mismo juego"],["1952","Parker Brothers lo vende como «Hex»"],["década de 1950","Shannon construye una máquina eléctrica que juega al hex"],["1957","Gardner lo presenta en su columna"],["1979","Gale muestra su relación con el teorema del punto fijo"],["década de 2010","Se resuelven por computadora los tableros hasta 9 × 9"]]},"foxgeese":{"title":"El zorro, los gansos y las piezas de plata del rey","lead":"Un zorro y muchos gansos: la larga historia de un «juego de caza» en el que los dos bandos no son iguales.","s":["En el zorro y los gansos, un único zorro salta sobre los gansos para comérselos, mientras los gansos intentan acorralarlo para que no pueda moverse. Cada bando tiene reglas distintas, sobre un tablero en cruz de 33 puntos unidos por líneas.","Una pista temprana es el «halatafl» de la saga islandesa de Grettir, escrita hacia el siglo XIV. Significa «tablero de la cola», y la cola sería la del zorro. Probablemente era una rama de los juegos nórdicos de tafl.","En Inglaterra, las cuentas del rey Eduardo IV, del siglo XV, registran la compra de «dos zorros y 26 sabuesos de plata sobredorada»: piezas para dos juegos, llamados entonces al parecer «zorro y sabuesos».","Con los 13 gansos originales el zorro era demasiado fuerte, así que se difundieron formas de jugar con más gansos. Se dice que en el siglo XIX la reina Victoria era aficionada al juego.","El mismo tablero en cruz sirve para el solitario de clavijas, de un solo jugador. Los juegos de caza en que un tigre o un lobo persigue a su presa, como el bagh-chal de Nepal, existen en todo el mundo. En el Atlas puedes jugar al zorro y los gansos y al solitario."],"quiz":[["¿Qué significa «hala» en halatafl?","Cola","Zorro","Rey","Nieve"],["¿Qué piezas aparecen en las cuentas de Eduardo IV?","Zorros y sabuesos de plata","Gansos de oro","Un rey de marfil","Dados de madera"],["¿Qué juego de un jugador usa el mismo tablero en cruz?","El solitario de clavijas","El sudoku","El solitario de cartas","El tangram"]],"kf":["Un zorro contra 13 gansos (más tarde 17) en un tablero en cruz de 33 puntos","El zorro captura saltando; los gansos ganan si lo acorralan sin que pueda moverse","El mismo tablero sirve para el solitario de clavijas, y hay juegos de caza así en todo el mundo"],"more":[{"h":"Uno contra trece","p":["El zorro avanza un paso por las líneas y captura saltando sobre un ganso contiguo si el punto de detrás está vacío; como en las damas, puede encadenar varios saltos. Los gansos no capturan y, en muchas versiones, tampoco pueden retroceder.","Los gansos buscan cerrar filas sin huecos, acorralar al zorro y dejarlo sin jugada. Se dice que con trece gansos el zorro lleva demasiada ventaja; con diecisiete gansos que no pueden retroceder, jugando bien ganan los gansos."],"cap":["Tablero de zorro y gansos: 33 puntos en cruz unidos por líneas. Trece gansos arriba; el zorro (naranja) puede comerse el ganso que tiene delante (×) saltándolo hasta el punto vacío de detrás"]},{"h":"La familia de los juegos de caza","p":["Unas pocas piezas fuertes persiguen a muchas débiles: hay juegos de caza así en todo el mundo. En el bagh-chal de Nepal, cuatro tigres cazan veinte cabras en un tablero de 5 × 5; en 2004 se calculó que, con juego perfecto, es tablas.","El asalto, popular en la Alemania del siglo XIX, usa el mismo tablero en cruz: dos oficiales contra veinticuatro soldados. Aquí los oficiales defienden una fortaleza que los soldados intentan tomar."],"cap":["Juegos de caza en cifras: cazadores a la izquierda (naranja), presas a la derecha (blanco). De arriba abajo: zorro y gansos (1:13), la versión con más gansos (1:17), el bagh-chal de Nepal (4:20) y el asalto (2:24)"]},{"h":"De las piezas del rey al solitario","p":["Las cuentas de Eduardo IV de Inglaterra (reinó 1461–83) registran la compra de piezas de plata dorada para un juego de zorro y sabuesos. También era un pasatiempo de reyes y nobles.","El mismo tablero en cruz de 33 agujeros se usa para el solitario de clavijas, que se juega a solas. Un grabado francés de 1697 muestra a una dama noble jugándolo: uno de los registros más antiguos de este solitario."],"cap":[]}],"tl":[["h. s. XIV","El «hala-tafl» aparece en la islandesa Saga de Grettir"],["finales s. XV","Eduardo IV compra piezas de plata para zorro y sabuesos"],["1697","Un grabado francés muestra a una dama jugando al solitario"],["s. XIX","Se dice que la reina Victoria disfrutaba del juego"],["s. XIX","El asalto, en el mismo tablero, se pone de moda en Alemania"],["2004","Se demuestra que el bagh-chal de Nepal es tablas con juego perfecto"]]},"latrunculi":{"title":"El tablero de los soldados romanos","lead":"Un juego que apasionaba a los romanos, llamado como los soldados a sueldo. No queda ningún reglamento: solo poemas, anécdotas y tableros salidos de la tierra.","s":["El ludus latrunculorum era un juego de batalla para dos de la antigua Roma. Latrunculi significaba en origen mercenarios o bandidos, y las piezas representaban soldados.","Las piezas se movían sobre una cuadrícula, y una pieza atrapada entre dos enemigas era capturada. Un poema del siglo I, la Laus Pisonis, describe piezas que avanzan y retroceden, y una pieza cercada hasta no poder moverse.","El filósofo Séneca cuenta la historia de Julio Cano, condenado a muerte por el emperador Calígula. Cuando el centurión vino a buscarlo, Cano jugaba a los latrunculi; contó las piezas y le dijo a su rival que no presumiera, tras su muerte, de haber ganado.","Se han hallado tableros por todo el imperio. Las cuadrículas grabadas en piedras de fuertes y ciudades van más o menos de 8 × 8 a 12 × 12. Una tumba del siglo I en Stanway (Inglaterra) conservaba piezas de vidrio aún dispuestas sobre su tablero.","No se conserva ningún reglamento detallado: las reglas actuales son reconstrucciones de investigadores. El latrunculi del Atlas se basa en una de ellas."],"quiz":[["¿Cómo se captura una pieza en el latrunculi?","Atrapándola entre dos piezas","Saltando sobre ella","Con una tirada de dados","Rodeando al rey"],["¿Quién jugaba a los latrunculi cuando vinieron a llevarlo a la ejecución?","Julio Cano","César","Nerón","Cicerón"],["¿Qué seguía sobre el tablero en la tumba de Stanway?","Piezas de vidrio","Monedas de oro","Piezas de ajedrez","Naipes"]],"kf":["Un juego de batalla para dos de la antigua Roma, con piezas vistas como soldados","Una pieza atrapada entre dos enemigas se captura; también se mencionan las piezas que no pueden moverse","No queda reglamento: se reconstruye a partir de poemas, anécdotas y tableros excavados"],"more":[{"h":"Atrapar y cercar","p":["La fuente más completa para las reconstrucciones es el poema del siglo I Laus Pisonis. Describe el juego como un campo de batalla: una pieza avanza para tentar al enemigo, otra le guarda las espaldas, y la que queda entre dos enemigas se pierde.","El poema habla también de una pieza cercada que no puede moverse, por lo que muchas reconstrucciones añaden una regla para las piezas bloqueadas además de la captura por encierro. Los juegos de tafl nórdicos usan una captura muy parecida."],"cap":["La captura en el latrunculi (reconstrucción). Izquierda: avanzando como indica la flecha azul, la pieza blanca queda entre dos negras y se captura (×). Derecha: una blanca bloqueada por los cuatro lados no puede moverse"]},{"h":"Un tablero de dos caras","p":["En un poema para acompañar un regalo, el poeta Marcial (siglo I) describe un tablero en el que por un lado las piezas avanzan según los dados y por el otro luchan soldados de dos colores: un juego de azar y uno de ingenio en una sola tabla.","Se cree que la cara de los dados es el juego de carreras llamado «doce líneas», antecesor de la tabula y del backgammon. La torre de dados (pyrgus) de la colección del museo es otro objeto que usaban los romanos."],"cap":["El tablero de dos caras de Marcial, imaginado: en una cara, una carrera de doce líneas con dados; en la otra, la cuadrícula de los soldados"]},{"h":"Tableros salidos de la tierra","p":["Los soldados romanos grababan cuadrículas en las piedras y suelos de sus fuertes para jugar. Se han hallado tableros grabados cerca del Muro de Adriano en Britania, y en Alemania, España y el norte de África.","En la tumba de Stanway (mediados del siglo I), el tablero de madera se había podrido, pero las piezas de vidrio blancas y azules seguían en su sitio, como a mitad de partida. Su dueño quizá fuera médico: se enterraron instrumentos médicos con ellas."],"cap":["Una torre de dados (pyrgus). Los romanos echaban los dados por torres así para evitar trampas"]}],"tl":[["s. I a. C.","Varrón menciona los latrunculi"],["finales s. I a. C.","Ovidio alude al juego en su poesía amorosa"],["s. I","La Laus Pisonis describe el juego en verso"],["mediados s. I","Se entierra en Stanway un tablero con sus piezas dispuestas"],["s. I","Séneca cuenta la anécdota de Julio Cano"],["finales s. I","Marcial escribe sobre un tablero de dos caras"],["1994","Schädler publica una reconstrucción de las reglas"]]},"amazons":{"title":"El juego que quema su propio tablero","lead":"Nacido en Argentina en 1988, el juego de las amazonas une el movimiento de la dama del ajedrez con el recuento de territorio del go.","s":["El juego de las amazonas es un juego para dos en un tablero de 10 × 10, con cuatro «amazonas» por bando. Lo inventó en 1988 el argentino Walter Zamkauskas.","Cada jugada tiene dos partes. Primero una amazona se mueve como la dama del ajedrez, en línea recta en horizontal, vertical o diagonal; luego, desde donde llega, dispara una flecha del mismo modo. La casilla donde cae la flecha ya no puede cruzarse nunca.","Cada jugada llena una casilla más, y pierde el jugador que ya no puede mover. No hay tablas.","Al final, las flechas dividen el tablero en habitaciones separadas. Entonces gana quien tiene más casillas vacías propias, así que la posición se juzga contando territorio, como en el go.","Hay más de 2.000 primeras jugadas posibles, lo que lo hace difícil incluso para las computadoras. Lo estudian matemáticos y es una prueba en torneos de computadoras."],"quiz":[["¿En qué país nació el juego de las amazonas?","Argentina","Brasil","España","México"],["¿Qué le pasa a la casilla donde cae una flecha?","Ya nadie puede cruzarla","Desaparece en el turno siguiente","Pasa a ser del rival","Suma un punto"],["¿Quién pierde en el juego de las amazonas?","El primero que no puede mover","El primero que pierde una pieza","El primero que forma territorio","El que agota su tiempo"]],"kf":["Un juego para dos en un tablero de 10 × 10, nacido en Argentina en 1988","La amazona se mueve como la dama y dispara una flecha desde donde llega para quemar una casilla","Pierde quien no puede mover; al final se cuenta el territorio como en el go"],"more":[{"h":"Mover y disparar","p":["Una amazona puede moverse cuantas casillas quiera, siempre que no salte otra pieza ni una flecha. Desde la casilla a la que llega dispara después una flecha, también con movimiento de dama, incluso hacia la casilla que acaba de dejar.","Nunca se captura nada. En cambio, cada jugada cierra una casilla del tablero y corta los caminos del rival: ataque y defensa se deciden con la misma flecha."],"cap":["Una jugada de las amazonas. La amazona blanca se mueve como la dama (azul) y desde donde llega dispara una flecha igual (rojo). La casilla de la flecha queda cerrada para siempre"]},{"h":"Un tablero partido en habitaciones","p":["Con el avance de la partida, las flechas tabican el tablero en habitaciones. Si en una solo hay amazonas de un jugador, sus casillas vacías son solo suyas, para gastarlas una por jugada.","Entonces la partida se vuelve un recuento: quien tiene más casillas utilizables puede mover durante más tiempo. Esto encaja con la teoría de juegos combinatorios, y Elwyn Berlekamp, entre otros, estudió a fondo los finales de las amazonas."],"cap":["Posición final (ilustración). Muros de casillas quemadas dividen el tablero en cuatro habitaciones: las verdes solo puede usarlas el blanco, las azules solo el negro. Quien tiene más casillas vacías puede seguir moviendo más tiempo"]},{"h":"Nacido en una revista, disputado por computadoras","p":["Se dice que el juego apareció por primera vez en una revista argentina de acertijos. Sus reglas son breves y basta un tablero de ajedrez con algunas piezas, así que se extendió por el mundo gracias a internet.","Con más de 2.000 primeras jugadas posibles, la apertura exige una visión del tablero entero, como en el go. Desde los años 2000 es una prueba de los torneos de computadoras, donde compiten programas entre sí."],"cap":[]}],"tl":[["1988","Walter Zamkauskas inventa el juego de las amazonas"],["década de 1990","Se extiende por el mundo gracias a internet"],["2000","Berlekamp publica estudios matemáticos sobre sus finales"],["década de 2000","Pasa a ser una prueba de la Olimpiada de Computadoras"]]},"loa":{"game":"Lines of Action","title":"Fichas que avanzan tanto como cuentas","lead":"Lines of Action llegó al mundo en un libro de Sid Sackson de 1969. No se gana capturando, sino uniendo todas tus fichas en un solo grupo.","s":["Lines of Action (LOA) es un juego para dos en un tablero de 8 × 8, con doce fichas por bando. Lo inventó Claude Soucie y se dio a conocer en 1969 en A Gamut of Games, un libro del coleccionista de juegos Sid Sackson.","Una ficha avanza en línea recta, en horizontal, vertical o diagonal. La distancia es exactamente el número de fichas —propias y rivales— que hay en esa línea. Cada jugada cambia los recuentos, y con ellos las distancias.","Puedes saltar tus propias fichas, pero nunca las del rival. Si caes sobre una ficha rival, la capturas.","El objetivo es unir todas tus fichas en un solo grupo, tocándose en horizontal, vertical o diagonal. Capturar reduce el ejército rival, lo que a veces incluso le ayuda a unirse: un giro curioso.","Las reglas son breves, pero es difícil calcular a fondo, así que se ha usado mucho en la investigación de IA para juegos. Programas de la Universidad de Maastricht, en los Países Bajos, han ganado muchas veces torneos de computadoras."],"quiz":[["¿Qué decide cuántas casillas avanza una ficha?","El número de fichas en esa línea","La tirada de un dado","El número de fichas capturadas hasta ahora","Siempre son tres casillas"],["¿Cómo se gana en LOA?","Uniendo todas tus fichas en un solo grupo","Capturando todas las fichas rivales","Llegando al borde opuesto del tablero","Capturando al rey rival"],["¿Quién presentó LOA en un libro de 1969?","Sid Sackson","Martin Gardner","Edmond Hoyle","H. J. R. Murray"]],"kf":["Juego para dos en un tablero de 8 × 8, doce fichas cada uno; inventado por Claude Soucie y presentado en un libro de Sid Sackson de 1969","Una ficha avanza exactamente tantas casillas como fichas hay en su línea; puede saltar las propias, nunca las rivales","No gana quien más captura, sino quien primero une todas sus fichas en un solo grupo"],"more":[{"h":"Contar y avanzar","p":["Si, por ejemplo, hay tres fichas en la fila que pasa por una ficha, esa ficha avanza exactamente tres casillas por ella, ni más ni menos. Puede pasar por encima de sus propias fichas, pero si hay una ficha rival en medio, no puede ir en esa dirección.","Cada ficha está en cuatro líneas —una fila, una columna y dos diagonales—, cada una con su propio recuento. Cuando una ficha se mueve, cambian los recuentos de varias líneas a su alrededor, así que las «distancias» del tablero se barajan en cada jugada. Por eso LOA es tan difícil de prever."],"cap":["A dónde puede ir la ficha negra de la que salen las flechas. En la fila hay 3 fichas, así que avanza 3 (saltar la propia está permitido); en la columna hay 2, así que avanza 2 y captura una ficha blanca. En la diagonal también hay 3, pero una ficha blanca corta el paso (×)"]},{"h":"Un solo grupo gana","p":["Las fichas cuentan como unidas cuando se tocan en horizontal, vertical o diagonal. Quien se queda con una sola ficha también está «unido», así que capturar demasiado puede incluso regalar la victoria al rival.","Qué pasa cuando una jugada une a ambos bandos a la vez depende de la edición y del torneo. La primera edición del libro de Sackson lo daba como tablas, una edición posterior como victoria de quien movió, y la mayoría de los torneos actuales lo cuentan como tablas. En el LOA de este Atlas gana quien movió."],"cap":["Una posición ganadora. Las fichas blancas (borde dorado) se tocan entre sí, diagonales incluidas, y forman un solo grupo. Las negras siguen divididas en tres (punteado)"]},{"h":"Un juego por el que pelearon las computadoras","p":["Con un tablero pequeño, reglas breves y juego profundo, LOA se convirtió en banco de pruebas de la IA para juegos. MIA, el programa de Mark Winands en la Universidad de Maastricht, ganó la Olimpiada de Computadoras en 2003, 2004, 2006 y 2009, y su trabajo se reunió en su tesis doctoral de 2004, Informed Search in Complex Games.","En 2008 Winands resolvió LOA en un tablero reducido de 6 × 6 y mostró que, con juego perfecto, gana el primer jugador (negras). Se cree que el juego completo de 8 × 8 sigue sin resolver. Los jugadores humanos también se enfrentan en un campeonato del mundo que se celebra cada año en la Mind Sports Olympiad."],"cap":[]}],"tl":[["c. 1960","Se atribuye a Claude Soucie la invención de LOA"],["1969","Se presenta en A Gamut of Games, de Sid Sackson"],["2003","MIA, de Winands, gana la Olimpiada de Computadoras (y de nuevo en 2004, 2006 y 2009)"],["2004","Tesis doctoral de Winands, Informed Search in Complex Games"],["2008","Se resuelve LOA de 6 × 6: gana el primer jugador"]]},"konane":{"title":"El juego de lava negra y coral blanco","lead":"El kōnane, jugado por el pueblo de Hawái, quedó escrito en el relato del viaje de Cook; en el siglo XX los matemáticos lo desmenuzaron con la teoría de juegos combinatorios.","s":["El kōnane es un juego para dos de los nativos hawaianos. Piedras negras y blancas llenan el tablero alternadas, sin huecos, y los jugadores capturan saltando sobre las piedras del rival.","Antiguamente las piedras negras eran de lava y las blancas, trozos de coral. El tablero, llamado papamū, era una gran piedra plana con hoyuelos picados en la superficie. Se dice que el juego aparece incluso en el Kumulipo, el canto hawaiano de la creación.","Primero las negras retiran una de sus piedras y luego las blancas retiran una vecina. Los dos huecos que quedan son el punto de partida de los saltos.","Cada jugada es una captura. Una piedra salta en horizontal o vertical sobre una piedra rival contigua y cae en la casilla vacía de detrás. Mientras siga en línea recta, puede seguir saltando.","Pierde quien ya no tiene capturas; no hay tablas. Este diseño sencillo despertó más tarde el interés de los matemáticos."],"quiz":[["¿De qué eran las antiguas piedras blancas del kōnane?","De coral","De marfil","De mármol blanco","De hueso"],["¿Quién pierde en el kōnane?","Quien ya no tiene capturas","Quien se queda sin piedras","Quien llega antes al borde del tablero","Quien se queda con una sola piedra"],["Al encadenar saltos, ¿qué no está permitido?","Cambiar de dirección","Capturar más de una piedra en un turno","Detenerse a mitad","Caer junto a una piedra propia"]],"kf":["Juego para dos de los nativos hawaianos que empieza con piedras negras (lava) y blancas (coral) alternadas por todo el tablero","Cada jugada salta en horizontal o vertical sobre una piedra rival y la captura; en línea recta se puede volver a saltar","Pierde quien se queda sin capturas; los matemáticos lo estudiaron con la teoría de juegos combinatorios"],"more":[{"h":"Saltar y capturar","p":["Los saltos son solo en horizontal o vertical, nunca en diagonal. Si la casilla tras una piedra rival contigua está vacía, la piedra salta, cae allí y la piedra saltada se retira del tablero.","Si desde donde cae puede volver a saltar, puede seguir en la misma dirección. No puede cambiar de dirección en el camino, y puede detenerse cuando quiera. En cada turno se mueve una sola piedra."],"cap":["Una piedra blanca salta dos veces hacia la derecha en un turno y captura dos piedras negras (azul 1 y 2). No puede girar y saltar hacia abajo desde donde cae (×)"]},{"h":"Los dos primeros huecos","p":["En un tablero lleno de piedras nadie puede saltar. Por eso las negras, que empiezan, retiran una de sus piedras de las cuatro casillas centrales o de una esquina. Luego las blancas retiran una de las suyas que toque ese hueco en horizontal o vertical.","Los dos huecos contiguos son los primeros lugares de aterrizaje. Dónde se abren condiciona toda la partida."],"cap":["Las dos maneras de empezar. Las negras retiran una de sus piedras de las cuatro centrales (izquierda) o de una esquina (derecha) (1); luego las blancas retiran una vecina (2)"]},{"h":"Tableros de piedra y 238 casillas","p":["El relato del tercer viaje de James Cook (tomo III, publicado en 1784) describe un juego de piedras visto en Hawái como «muy parecido a nuestras damas», aunque más intrincado. Lo escribió el oficial James King, que cuenta que el tablero medía unos dos pies y tenía 238 casillas, catorce por fila.","No había un tamaño fijo: se conocen tableros de 6 × 7, 9 × 13, 13 × 20 y otros. Hoy suele jugarse en un tablero cuadrado y par, y este Atlas ofrece 6 × 6, 8 × 8 y 10 × 10. En el Parque Histórico Nacional Puʻuhonua o Hōnaunau, en la isla de Hawái, aún se ven papamū tallados en piedra."],"cap":["Tamaños de tablero comparados: el de 14 × 17 (238 casillas) descrito en el relato del viaje de Cook, y los de 10 × 10, 8 × 8 y 6 × 6 que se juegan en este Atlas"]},{"h":"Un juego que encontraron los matemáticos","p":["En el kōnane pierde quien no puede mover, y al final el tablero se parte en zonas independientes: encaja a la perfección en la teoría de juegos combinatorios de Elwyn Berlekamp y sus colegas. Michael Ernst escribió con Berlekamp un breve artículo sobre el kōnane en 1993 y, en un artículo de 1995, calculó los valores de muchas posiciones.","Vinieron más: Alice Chan y Alice Tsai estudiaron el kōnane de una sola fila (2002), y Bob Hearn mostró que en tableros cada vez mayores decidir quién gana se vuelve extremadamente difícil (PSPACE-completo). Un juego de saltar piedras se había convertido en tema de la teoría de la computación."],"cap":[]}],"tl":[["1778","Los barcos de Cook llegan a Hawái"],["1784","Se publica el relato del tercer viaje de Cook, con la descripción del juego de piedras por King"],["1993","Ernst y Berlekamp escriben un breve artículo sobre el kōnane"],["1995","Artículo de Ernst «Playing Konane Mathematically»"],["2002","Chan y Tsai resumen sus resultados sobre el kōnane de una fila"]]},"peg":{"title":"El rompecabezas de saltos nacido en una corte real","lead":"El solitario de clavijas se jugaba a finales del siglo XVII en la corte francesa de Luis XIV. Un sencillo rompecabezas de ir quitando clavijas una a una que fascina a los matemáticos desde entonces.","s":["El solitario de clavijas es un rompecabezas para una sola persona. Las clavijas llenan los agujeros del tablero y solo queda uno vacío.","Una clavija salta sobre una vecina, en horizontal o vertical, hasta el agujero vacío de detrás. La clavija saltada se retira del tablero.","El objetivo es seguir saltando hasta que quede una sola clavija. Dejarla justo en el centro es el final perfecto.","Los primeros registros firmes proceden de la Francia de finales del siglo XVII, de la corte de Luis XIV. En 1697 la revista Mercure galant publicó el tablero y sus reglas, y un grabado muestra a una dama con un tablero a su lado.","Parece fácil, pero es difícil. El matemático Leibniz se interesó por él, y en el siglo XX los matemáticos explicaron, coloreando los agujeros, por qué algunos problemas no tienen solución."],"quiz":[["¿Qué le pasa a la clavija que es saltada?","Se retira del tablero","Pasa a ser del rival","Se desliza al agujero de al lado","Vuelve en el turno siguiente"],["¿Cuántos agujeros tiene el tablero inglés?","33","37","45","64"],["¿De dónde vienen los primeros registros firmes del solitario?","De la corte francesa de Luis XIV, a finales del siglo XVII","De las termas de la antigua Roma","De una escuela de templo del Japón Edo","De una taberna de la América del siglo XIX"]],"kf":["Rompecabezas de saltos para una persona: se salta para quitar clavijas y se gana dejando una sola","Los registros firmes empiezan hacia 1697 en la corte francesa de Luis XIV; los tableros clásicos tienen 33 (inglés) y 37 (europeo) agujeros","Pintar los agujeros con tres colores permite saber de antemano qué problemas no tienen solución"],"more":[{"h":"Saltar y quitar","p":["Solo se salta en horizontal o vertical, nunca en diagonal (salvo en tableros con líneas diagonales, como el triangular). Cada salto quita una clavija, así que empezando con 32 hacen falta 31 saltos para quedarse con una.","Una misma clavija puede saltar varias veces seguidas. Si se cuenta esa cadena como una jugada, el problema de centro a centro del tablero inglés se resuelve en 18 jugadas. Ernest Bergholt halló esa solución en 1912, y en 1964 John Beasley demostró que no puede hacerse en menos."],"cap":["La primera jugada en el tablero inglés. Con el centro vacío, la clavija de arriba salta sobre la de abajo hasta el centro (azul); la saltada se retira (×)"]},{"h":"De pasatiempo de la corte","p":["La historia segura del solitario se remonta a la corte de Luis XIV hacia 1697. Ese agosto la revista Mercure galant describió el tablero, las reglas y algunos problemas, y el grabador Claude-Auguste Berey retrató a la princesa de Soubise con un tablero a su lado.","También es famosa la historia de un noble encerrado en la Bastilla que lo inventó para matar el tiempo, pero es una leyenda que no puede confirmarse. Se dice que el tablero de 37 agujeros usado en Francia también existe desde el siglo XVII, mientras que el de 33, con las esquinas recortadas, se llama tablero inglés."],"cap":["Los dos tableros clásicos: inglés, de 33 agujeros (izquierda), y europeo, de 37 (derecha). El agujero vacío es el inicio habitual de cada uno"]},{"h":"Lo que revelan tres colores","p":["Pinta los agujeros con tres colores de modo que los colores sigan las diagonales. Así, tres agujeros seguidos, en horizontal o vertical, son siempre de tres colores distintos. Un salto quita una clavija a dos colores y añade una al tercero, de modo que los recuentos de los tres colores cambian juntos de par a impar.","En el tablero europeo con el centro vacío, cada color tiene 12 clavijas: todos pares. Cada salto solo alterna entre «todos pares» y «todos impares», así que nunca se llega a la posición de una última clavija —un color con 1 y los otros dos con 0—. En este tablero, el problema que empieza en el centro no tiene solución. La misma comprobación en el tablero inglés reduce a solo cinco los agujeros donde puede quedar la última clavija empezando desde el centro."],"cap":["El tablero europeo de 37 agujeros pintado con tres colores a lo largo de las diagonales. Con el centro vacío, cada color tiene 12 clavijas"]},{"h":"Un juguete para matemáticos","p":["Se cuenta que Leibniz escribió en una nota de 1710 que le gustaba jugarlo al revés, rellenando los agujeros que se habían saltado. Trabajar hacia atrás desde el final sigue siendo una forma básica de resolverlo.","Winning Ways (1982), de Berlekamp, Conway y Guy, analizó el rompecabezas a fondo y presentó las «funciones pagoda»: si se da a cada agujero una puntuación tal que ningún salto aumente el total, se puede demostrar que ciertos objetivos son imposibles. Se dice que en 1999 una búsqueda por computadora examinó todas las posiciones."],"cap":[]}],"tl":[["1697","Se juega en la corte de Luis XIV; el Mercure galant de agosto publica el tablero y las reglas"],["1710","Se dice que Leibniz escribe sobre jugarlo al revés"],["1912","Bergholt halla una solución de 18 jugadas en el tablero inglés"],["1964","Beasley demuestra que no hay solución de menos de 18 jugadas"],["1982","Winning Ways reúne su análisis, con las funciones pagoda"]]},"fanorona":{"title":"Capturar acercándose, capturar alejándose","lead":"El fanorona es el juego nacional de Madagascar. Según la leyenda decidió un trono, y en el siglo XXI las computadoras demostraron que con juego perfecto acaba en tablas.","s":["El fanorona es un juego para dos muy popular en Madagascar. Se juega en un tablero de 9 × 5 con líneas horizontales, verticales y diagonales, y 22 piezas por bando.","El tablero parece dos tableros de alquerque —un juego del mundo árabe y de Europa— puestos uno al lado del otro. Se cree que el alquerque llegó a la isla y allí se convirtió en un juego propio.","Su gran rasgo es la forma de capturar. Moverse hacia una pieza rival («aproximación») o alejarse de ella («retirada») captura toda la fila de piezas rivales de esa línea.","Capturar es obligatorio, y la pieza que ha capturado puede cambiar de dirección y seguir capturando. Un solo turno puede transformar el tablero: esa es la emoción del fanorona.","Querido desde hace siglos, tiene incluso la leyenda de un príncipe que perdió un trono por no poder dejar una partida. En 2007, investigadores neerlandeses mostraron con computadoras que con el mejor juego de ambos bandos es tablas."],"quiz":[["¿Qué tamaño tiene el tablero de fanorona?","9 × 5","8 × 8","7 × 7","6 × 6"],["¿Cuáles son las dos formas de capturar en el fanorona?","Aproximación y retirada","Saltar y encerrar","Rodear y empujar","Dados y sorteo"],["¿Qué mostraron las computadoras con el mejor juego?","Tablas","Gana el primer jugador","Gana el segundo jugador","Aún no se sabe nada"]],"kf":["Juego para dos de Madagascar: 22 piezas cada uno en un tablero de 9 × 5, con solo el centro vacío al empezar","Acercarse a una pieza rival (aproximación) o alejarse (retirada) captura toda la fila de esa línea","En 2007 las computadoras mostraron que con el mejor juego es tablas"],"more":[{"h":"Aproximación y retirada","p":["En la aproximación, si justo después del punto de llegada hay una pieza rival, se capturan esa pieza y todas las rivales alineadas detrás sin hueco. La retirada es al revés: se capturan la pieza rival que estaba justo detrás del punto de partida y las alineadas tras ella.","Como un solo paso puede eliminar varias piezas, los ejércitos menguan rápido desde el principio. Si una jugada permite a la vez aproximación y retirada, el jugador elige una."],"cap":["Las dos capturas. Arriba: el blanco avanza un paso a la derecha hacia una pieza negra y captura las tres negras en fila (aproximación). Abajo: el blanco avanza a la derecha alejándose de una negra y captura las dos negras de detrás (retirada)"]},{"h":"Dos tableros de alquerque juntos","p":["El tablero tiene 5 × 9 = 45 puntos; además de las líneas horizontales y verticales, hay diagonales que pasan por un punto sí y otro no. Las piezas avanzan un paso por una línea hasta un punto vecino. Al empezar solo está vacío el centro, así que la primera jugada es siempre una captura.","El tablero son dos tableros de alquerque de 5 × 5 unidos. El alquerque es un juego antiguo ya nombrado en un libro árabe del siglo X, y se cree que el fanorona surgió de él. No se sabe cuándo ni cómo llegó a la isla; algunos libros hablan del siglo XVII."],"cap":["La posición inicial: 22 piezas negras y 22 blancas en los 9 × 5 puntos, con solo el punto central vacío. Los cuadros discontinuos marcan dos tableros de alquerque de 5 × 5"]},{"h":"Cadenas de capturas","p":["Una pieza que ha capturado puede volver a capturar. Pero cada paso debe ir en una dirección distinta y no puede volver a un punto ya visitado. Seguir o no es decisión del jugador.","Cuando la cadena sale bien, un turno puede llevarse casi la mitad de las piezas rivales. Pero si termina en mal sitio, la pieza es recapturada enseguida."],"cap":["Una cadena de capturas. El blanco (1) se acerca hacia la derecha y captura dos; (2) se retira hacia arriba y captura dos; (3) se acerca hacia la izquierda y captura dos. Tras (1) no puede seguir hacia la derecha (×)"]},{"h":"Un trono y las computadoras","p":["Cuenta la leyenda que Ralambo, rey de Imerina hacia el siglo XVI, fingió estar enfermo para que heredara el trono el primer hijo en volver. El mayor, Andriantompokoindrindra, no pudo dejar una difícil posición de fanorona, y el menor, Andrianjaka, fue rey. Otra historia dice que durante la invasión francesa de 1895 el bando de la reina confió en una partida ritual de fanorona; ninguno de los dos relatos puede confirmarse.","En 2007, Maarten Schadd y sus colegas de la Universidad de Maastricht, en los Países Bajos, calcularon todas las posiciones de siete piezas o menos y, con la búsqueda por números de prueba, demostraron que la posición inicial es tablas (el artículo salió en 2008). El cálculo llevó más de una semana en una sola máquina."],"cap":[]}],"tl":[["c. siglo XVI","La leyenda de la sucesión del rey Ralambo y el fanorona"],["c. siglo XVII","Una opinión sobre cuándo surgió el fanorona del alquerque"],["1895","La leyenda de una partida ritual de fanorona durante la invasión francesa"],["2007","Schadd y sus colegas muestran por computadora que es tablas"],["2008","El artículo «Best Play in Fanorona Leads to Draw»"]]},"janggi":{"title":"Un tablero sin río y un cañón que salta una sola vez","lead":"El janggi, muy querido en Corea, usa el mismo tablero de 9 × 10 que el xiangqi chino, pero quitó el río y cambió el movimiento de las piezas.","s":["El janggi es un juego de ajedrez para dos que se juega en Corea desde hace mucho. Se cree que procede del xiangqi chino, y sus piezas se colocan en los puntos de una cuadrícula de 9 × 10 líneas.","A diferencia del xiangqi, el tablero no tiene «río» en el centro, así que elefantes y soldados pueden ir a cualquier parte. El general (rey) empieza en el centro de su «palacio» y nunca puede salir de él.","Los bandos son Cho (azul o verde) y Han (rojo). Las piezas son octogonales, y cuanto más fuerte es la pieza, más grande se hace. Empieza Cho.","Antes de jugar, cada bando elige una de cuatro formas de colocar caballos y elefantes. Han coloca primero y Cho decide después de verlo, así que el tira y afloja empieza antes de la primera jugada.","Además del jaque mate, la partida puede decidirse por puntos. Cho, que empieza, parte de 72 puntos; Han recibe un «deom» de 1,5 y parte de 73,5. Cada pieza perdida resta puntos."],"quiz":[["¿Qué no tiene el tablero de janggi?","Un río en el centro","Palacios","Diagonales en los palacios","90 puntos"],["¿Qué debe hacer siempre el cañón para moverse?","Saltar exactamente una pieza","Estar junto a una pieza rival","Estar dentro de un palacio","No estar en jaque"],["Al contar puntos, ¿cuánto «deom» recibe Han, el segundo jugador?","1,5","0,5","3","6,5"]],"kf":["El ajedrez de Corea, nacido del xiangqi: un tablero de 9 × 10, pero sin río","El elefante mueve uno recto y dos en diagonal; el cañón se mueve y captura saltando exactamente una pieza","Cada bando elige una de cuatro colocaciones de caballos y elefantes; al contar puntos, Han recibe un deom de 1,5"],"more":[{"h":"Un tablero sin río y cuatro colocaciones","p":["El tablero de janggi tiene los mismos 9 × 10 puntos que el xiangqi, pero sin río en el centro. Cada palacio tiene diagonales en forma de X, y el general y los guardias se mueven paso a paso dentro de él, también por las diagonales. El general empieza en el centro mismo de su palacio.","Hay cuatro colocaciones, que resultan de intercambiar caballos y elefantes. Han coloca primero, y Cho elige después de verlo. Que los elefantes estén por dentro o por fuera cambia las líneas de ataque de la apertura."],"cap":["El tablero de janggi y la posición inicial. No hay río, y los palacios de arriba y abajo tienen diagonales. Los círculos discontinuos marcan dónde pueden intercambiarse caballos y elefantes; Han (arriba) y Cho (abajo) eligieron colocaciones distintas"]},{"h":"Caballo, elefante y puntos bloqueados","p":["El caballo avanza primero un punto en línea recta y luego uno en diagonal hacia fuera. El elefante llega más lejos: un punto recto y luego dos en diagonal. En ambos casos, una pieza en un punto del camino bloquea esa dirección.","El elefante del xiangqi no puede cruzar el río y solo se mueve dos puntos en diagonal, pero el del janggi tiene patas largas y recorre todo el tablero. A cambio, su camino se bloquea con facilidad."],"cap":["El caballo (izquierda) mueve uno recto y uno en diagonal; el elefante (derecha), uno recto y dos en diagonal. Los puntos azules muestran adónde pueden ir. Una pieza en un punto del camino bloquea esa dirección (×)"]},{"h":"El cañón que salta una sola vez","p":["El cañón debe saltar exactamente una pieza intermedia, tanto para moverse como para capturar. Si no hay nada en medio no puede moverse, así que en la posición inicial los cañones están quietos.","Ni la pieza saltada ni la capturada pueden ser un cañón, de modo que dos cañones solo pueden mirarse fijamente. Comparado con el cañón del xiangqi, que se mueve libremente cuando no captura, es una pieza mucho más exigente."],"cap":["El cañón. Arriba: salta exactamente un soldado y va a un punto de más allá, o captura el carro (azul). En medio: no puede saltar si la pieza intermedia es un cañón. Abajo: un cañón no puede capturar a otro cañón (×)"]},{"h":"Generales enfrentados y puntos","p":["Cuando los dos generales se enfrentan en una línea sin nada en medio, se llama «bikjang». Según una norma, si el bando enfrentado no lo deshace, la partida es tablas. Las reglas tradicionales también permiten pasar el turno si no se está en jaque.","Los valores son carro 13, cañón 7, caballo 5, elefante 3, guardia 3 y soldado 2. Cho suma 72 puntos y Han 73,5 con el deom. Por el medio punto, nunca puede haber empate a puntos. En el janggi de este Atlas, estos puntos deciden la partida cuando una posición se repite tres veces o tras 200 jugadas."],"cap":[]}],"tl":[["Período Goryeo","Una opinión sostiene que ya se jugaba (la fecha de llegada se discute)"],["siglo XVIII","Se dice que se registra una variante mayor, el gwangsanghui"],["1895","Korean Games, de Stewart Culin, muestra un dibujo de hombres jugando al janggi"],["2009","Se dice que se celebra el primer torneo internacional en Harbin, China"]]},"pic":{"tlvmirror":"Espejo TLV (Han oriental, Museo de Arte de Cleveland)","kotoboard":"Las cuatro artes (periodo Edo, h. 1620-1650, Museo de Arte de Cleveland)","homerbg":"Winslow Homer, Backgammon (grabado en madera, h. 1877, Museo de Arte de Cleveland)","trictrac":"Philips de Koninck, Los jugadores de tric-trac (dibujo, h. 1660, Museo de Arte de Cleveland)","gametable":"Mesa de juego con tableros de ajedrez y de molino (Maguncia, h. 1735, Museo de Arte de Cleveland)","kota":"El soberano de Kota adora a Krishna; en los escalones, un paño de chaupar en cruz (h. 1825, Museo de Arte de Cleveland)"},"mahjong":{"game":"Mahjong","title":"El juego de fichas con nombre de gorrión","lead":"El mahjong nació en la China del siglo XIX. Un juego de cartas se convirtió en fichas, causó furor en los Estados Unidos de los años veinte y en Japón se transformó en el riichi mahjong.","s":["El mahjong es un juego de fichas para cuatro personas. Usa 136 fichas (144 con las flores), y gana quien primero completa una mano con una forma determinada.","Nació en la China del siglo XIX. Sus raíces son juegos de «robar y descartar» con cartas que mostraban unidades de dinero, y se cree que hacia mediados de siglo las cartas de papel se convirtieron en fichas.","Las fichas más antiguas que se conservan son de hacia 1870 y se adquirieron en Ningbo, Shanghái y Fuzhou. Algunos libros dicen que nació en Ningbo; otros, que empezó como pasatiempo de pescadores de Fujian y Cantón.","«Máquè» significa gorrión, y una teoría deriva el nombre de un juego de cartas más antiguo, el madiao. La historia tan repetida de que lo inventó Confucio no tiene ningún fundamento.","En el siglo XX el mahjong cruzó los mares. Causó furor en los Estados Unidos de los años veinte, y en Japón la posterior regla del «riichi» lo convirtió en un juego propio."],"quiz":[["Sin las flores, ¿cuántas fichas tiene el mahjong?","136","144","108","152"],["¿Cuál es la forma básica de una mano ganadora?","Cuatro combinaciones y una pareja","Solo siete combinaciones","Trece fichas iguales","Tres combinaciones y dos parejas"],["¿En qué país causó furor el mahjong en los años veinte?","Estados Unidos","Rusia","Brasil","Egipto"]],"kf":["Un juego de fichas para cuatro nacido de juegos de cartas en la China del siglo XIX","Fichas numeradas de caracteres, círculos y bambúes, más vientos y dragones; se gana con cuatro combinaciones y una pareja","Furor en la América de los años veinte; en el Japón de posguerra creció el riichi mahjong"],"more":[{"h":"136 fichas","p":["Las fichas numeradas forman tres palos —caracteres, círculos y bambúes—, cada uno del 1 al 9 con cuatro copias: 108 fichas. Si se suman cuatro de cada viento (este, sur, oeste y norte) y de cada dragón (blanco, verde y rojo), salen 136.","Muchas formas chinas de jugar usan también ocho flores: ciruelo, orquídea, crisantemo y bambú, y las cuatro estaciones. No forman parte de la mano; al robarlas se apartan y suman puntos. El mahjong japonés suele prescindir de ellas."],"cap":["Los tipos de fichas. Caracteres, círculos y bambúes del 1 al 9, los vientos (este, sur, oeste, norte) y los dragones (blanco, verde, rojo), cuatro de cada: 136. Con las ocho flores bajo la línea de puntos (una de cada): 144"]},{"h":"Cuatro combinaciones y una pareja","p":["La mano tiene 13 fichas; se roba una y se descarta una, una y otra vez. Cuando una ficha robada, o una que otro descarta, completa cuatro combinaciones y una pareja, la mano gana.","Las combinaciones son el chow (tres números seguidos de un palo), el pung (tres fichas iguales) y el kong (cuatro iguales). También se pueden formar reclamando el descarte de otro jugador, así que la partida es un largo duelo para decidir qué tomar y qué soltar."],"cap":["La forma básica de una mano ganadora: cuatro combinaciones —chow (tres seguidas del mismo palo), pung (tres iguales) o kong (cuatro iguales)— y una pareja"]},{"h":"El mahjong cruza los mares","p":["En 1920 Joseph Park Babcock publicó un reglamento en inglés, y una tienda de Nueva York empezó a importar juegos desde China. El mahjong causó furor en la América de los años veinte, y la National Mah Jongg League, fundada en 1937, mantiene viva una forma estadounidense de jugar.","Llegó a Japón en los años veinte; se dice que en 1924 Saburo Hirayama abrió un local y una escuela en Tokio, y en 1929 se fundó la Liga Japonesa de Mahjong con el escritor Kan Kikuchi al frente. En 1952, tras la guerra, se dice que Daizō Amano publicó en un periódico reglas con «riichi», y de ahí se extendió el riichi mahjong japonés."],"cap":["Cómo se extendió el mahjong: de China a Estados Unidos y Japón en los años veinte; reglas del riichi en Japón en 1952 y reglas oficiales chinas en 1998"]},{"h":"Leyendas e historia real","p":["El mahjong tiene muchas leyendas de origen. La de que lo creó Confucio no tiene base. La de un hombre de Ningbo llamado Chen Yumen que lo inventó probablemente también es falsa, pues nunca se han encontrado los papeles de los que supuestamente procede.","Lo seguro es que los juegos chinos del siglo XIX de robar y descartar con cartas de dinero se convirtieron en un juego de fichas. Los primeros juegos no tenían flores ni dragón verde, sino fichas de «rey» y otras. En 1998 China fijó además unas reglas oficiales nacionales."],"cap":[]}],"tl":[["mediados del s. XIX","Se cree que los juegos de cartas pasan a ser de fichas"],["c. 1870","Los juegos más antiguos conservados (Ningbo, Shanghái, Fuzhou)"],["1920","Babcock publica un reglamento en inglés"],["1929","Se funda la Liga Japonesa de Mahjong"],["1952","Se publican las «reglas Hochi» con riichi"],["1998","China fija reglas oficiales nacionales"]],"figL":{"hand":["Chow","Pung","Kong","Chow","Pareja"],"spread":[["c. 1870","Ningbo, Shanghái","Fichas más antiguas"],["1920","Estados Unidos","Reglas de Babcock, furor"],["1920s","Japón","Llega; liga en 1929"],["1952","Japón","Reglas del riichi"],["1998","China","Reglas oficiales, 81 jugadas"]]}},"gomoku":{"title":"Gomoku: cuando el primer jugador era demasiado fuerte","lead":"El gomoku, que se juega con tablero y piedras de go, es querido en Japón desde el período Edo. Para frenar la ventaja del primer jugador nacieron las reglas del «renju», y al final las computadoras dieron la respuesta.","s":["El gomoku es un juego para dos con tablero y piedras de go. Negras y blancas colocan piedras por turnos, y gana quien primero alinea cinco propias en horizontal, vertical o diagonal.","Su origen no está claro. Hay quien lo remonta a la China antigua o al Japón de Heian, pero los registros firmes son del período Edo, y se dice que ya se jugaba a mediados del siglo XVIII.","Cuanto más se jugaba, más evidente era que las negras, que empiezan, tenían ventaja. Por eso en Japón se fueron creando reglas que imponían «jugadas prohibidas» solo a las negras.","En 1899 Ruikō Kuroiwa, del periódico Yorozu chōhō, llamó al juego «renju», que significa «perlas enlazadas».","En 1988 se fundó en Estocolmo (Suecia) la Federación Internacional de Renju (RIF), y se celebran campeonatos del mundo. Mientras tanto, las computadoras demostraron que el gomoku sin jugadas prohibidas es victoria del primer jugador."],"quiz":[["¿Cómo se gana al gomoku?","Alineando cinco piedras propias","Rodeando y capturando piedras","Dominando más de la mitad del tablero","Capturando cinco piedras rivales"],["¿Quién llamó al juego «renju»?","Ruikō Kuroiwa","Honinbō Dōsaku","Natsume Sōseki","Fukuzawa Yukichi"],["En el renju, ¿qué jugadas están prohibidas solo a las negras?","Doble tres, doble cuatro y línea larga","Jugar en el borde del tablero","Jugar junto a una piedra blanca","Rodear piedras rivales"]],"kf":["Un juego con tablero y piedras de go: gana quien alinea cinco; los registros firmes empiezan en el período Edo","Como las negras empiezan con ventaja, el renju les prohíbe el doble tres, el doble cuatro y la línea larga","En 1994 se demostró que el gomoku libre en 15 × 15 es victoria del primer jugador"],"more":[{"h":"Cinco en línea y el cuatro-tres","p":["Las partidas se deciden con una doble amenaza que el rival no puede bloquear de una vez. Un «cuatro» —a una piedra de cinco— debe bloquearse en el acto o se pierde. Un «tres» abierto por ambos lados, si se ignora, se convierte en un cuatro abierto que ya no se puede frenar.","Una jugada que crea a la vez un cuatro y un tres —un «cuatro-tres»— obliga a las blancas a tapar el cuatro, y luego el tres crece y gana. Mejorar en el gomoku es ver venir esta forma cada vez antes."],"cap":["Izquierda: cinco en diagonal ganan. Derecha: la piedra del anillo rojo forma a la vez un «cuatro» en horizontal (jugando en 4 hay cinco) y un «tres» abierto en vertical (los puntos 3): las blancas no pueden frenar ambos (cuatro-tres)"]},{"h":"Jugadas prohibidas solo a las negras","p":["En el renju las negras no pueden hacer doble tres, doble cuatro ni línea larga (seis o más en fila); hacerlo es falta y pierden. Las blancas no tienen jugadas prohibidas, e incluso seis o más en fila les dan la victoria.","Para ganar, las negras deben construir formas como el cuatro-tres que no estén prohibidas. Las blancas pueden incluso empujarlas a propósito hacia una jugada prohibida: un duelo de ingenio que da al renju su profundidad."],"cap":["Jugadas prohibidas a las negras en el renju (×). Desde la izquierda: «doble tres» (dos treses a la vez), «doble cuatro» (dos cuatros a la vez) y «línea larga» (seis o más)"]},{"h":"El gomoku resuelto","p":["En 1994 el neerlandés Victor Allis demostró por computadora que en el gomoku libre en un tablero de 15 × 15 el primer jugador, las negras, siempre puede ganar. En 2001 Wágner y Virág mostraron que el renju sin reglas de apertura también es victoria del primer jugador.","La gente sigue jugando porque las líneas ganadoras son demasiado complejas para memorizarlas. Los torneos usan «reglas de apertura» que fijan cómo se juegan las primeras jugadas —como Yamaguchi o Soosõrv-8— para que la lucha sea justa."],"cap":["La historia del gomoku y el renju: del gomoku del período Edo al nombre renju, la federación internacional y las pruebas por computadora"]},{"h":"Cinco en línea por todo el mundo","p":["En el siglo XIX el juego llegó a Gran Bretaña como «Go Bang». Hoy se juegan juegos parecidos en todo el mundo: el omok de Corea, el caro de Vietnam y el pente, en el que se capturan piedras por parejas.","El gomoku de este Atlas se juega en un tablero de 15 × 15 con tres reglas a elegir: renju, estándar y libre. Pruébalas y comprueba cuánto frenan al primer jugador las jugadas prohibidas del renju."],"cap":[]}],"tl":[["mediados del s. XVIII","Se dice que se juega al gomoku en el Japón de Edo"],["1856","El libro de gomoku más antiguo conservado, Gomoku Jōseki"],["1899","Ruikō Kuroiwa llama al juego renju"],["1988","Se funda en Estocolmo la Federación Internacional de Renju"],["1994","Allis demuestra que el gomoku libre es victoria del primer jugador"],["2001","Wágner y Virág muestran que el renju sin reglas de apertura gana el primero"]],"figL":{"time":[["1700s","Japón (Edo)","Se juega al gomoku"],["1899","Japón","Se llama «renju»"],["1988","Estocolmo","Nace la RIF"],["1994","Países Bajos","Gomoku: gana el primero"],["2001","Hungría","Renju: ganan negras"]]}},"carrom":{"title":"Carrom: un golpe de dedo hasta la tronera","lead":"En la India y el sur de Asia, familias y vecinos se reúnen para jugar al carrom. Las piezas, impulsadas con un dedo, van a parar a las troneras de las cuatro esquinas del tablero: un juego parecido al billar.","s":["El carrom se juega en un tablero liso de unos 74 centímetros de lado. Hay una tronera en cada esquina; juegan dos frente a frente, o cuatro por parejas.","Hay 19 piezas: 9 blancas, 9 negras y una «reina» roja. En tu turno colocas el «lanzador», más grande y pesado, sobre la línea que tienes delante —la línea de base— y lo impulsas con un dedo contra las piezas.","Gana quien mete todas las piezas de su color. Pero la reina roja solo es tuya si, tras meterla, metes a continuación una pieza propia para «cubrirla».","Se dice que el carrom nació en la India; en un palacio de Patiala, en el norte del país, aún se exhibe un tablero con superficie de vidrio. A comienzos del siglo XX ya había torneos estatales en la India.","En 1988 se fundó en Chennai (India) la Federación Internacional de Carrom, y desde 1991 se celebran campeonatos del mundo. Hay juegos parecidos de «golpe de dedo» por todo el mundo, como el crokinole de Canadá o el novuss de Letonia."],"quiz":[["Sin contar el lanzador, ¿cuántas piezas tiene el carrom?","19","16","24","32"],["¿Cómo se gana la reina roja?","Metiendo después una pieza propia (cubrirla)","Metiéndola al final","Metiéndola en el primer golpe","Golpeándola dos veces seguidas"],["¿En qué ciudad se fundó en 1988 la Federación Internacional de Carrom?","Chennai","Londres","Colombo","Bombay"]],"kf":["Un tablero con troneras en las esquinas: se impulsa el lanzador con un dedo para meter las piezas","9 blancas, 9 negras y una reina roja; la reina hay que «cubrirla» metiendo después una pieza propia","Se dice nacido en la India; Federación Internacional en 1988, campeonatos del mundo desde 1991"],"more":[{"h":"El tablero y sus 19 piezas","p":["Cada esquina del tablero tiene una tronera con red, y en cada lado hay una doble línea de base. El lanzador se coloca tocando ambas líneas y se impulsa desde ahí.","Al empezar, la reina va en el centro del tablero y las piezas blancas y negras se colocan a su alrededor en forma de flor. El primer golpe, que deshace la flor, es la «salida» que abre la partida."],"cap":["El tablero de carrom y la posición inicial. La reina roja en el centro, las piezas blancas y negras alrededor como una flor. Troneras en las esquinas, una doble línea de base en cada lado; el lanzador (anillo azul) se coloca en la línea de base cercana"]},{"h":"Golpear y rebotar","p":["El lanzador suele impulsarse con la uña; hay quien usa el dedo corazón, el índice o el pulgar. Si metes una pieza tuya vuelves a tirar; si no, le toca al rival.","Las bandas rebotan mucho, así que se usan los rebotes como en el billar. Meter el propio lanzador es falta y tiene castigo."],"cap":["El lanzador se impulsa (azul), rebota en la banda derecha y golpea una pieza blanca, que entra en la tronera de arriba a la derecha (rojo). Una pieza a la que no se puede apuntar directamente se alcanza con la banda"]},{"h":"Una familia de juegos de golpe","p":["Hay juegos de «golpe de dedo» como el carrom por todo el mundo. El crokinole de Canadá apunta a un agujero en el centro de un tablero redondo, y el pichenotte también se juega en Canadá desde hace mucho. Se dice que el propio carrom llegó a Norteamérica a fines del siglo XIX con misioneros que volvían de Asia.","Se dice que el novuss de Letonia y Estonia surgió en los años veinte; se juega con un taco pequeño en lugar del dedo. Llegó a ser uno de los deportes más populares de Letonia, y desde 1993 hay campeonatos internacionales."],"cap":["Primos del carrom que se juegan con el dedo o con un taco: el crokinole y el pichenotte de Canadá, el novuss de Letonia y Estonia y el couronne de Escandinavia"]},{"h":"Puntos y campeonatos del mundo","p":["Según las reglas internacionales, cubrir la reina suma 3 puntos, y gana quien llega primero a 25. En familia se juegan muchas variantes locales, como dar 5 puntos a la reina.","Se dice que en Sri Lanka hubo torneos serios desde hacia 1935, y en 1958 la India y Sri Lanka ya tenían federaciones oficiales. La Federación Internacional de Carrom (ICF) se fundó en Chennai en 1988, y los campeonatos del mundo se celebran desde 1991."],"cap":[]}],"tl":[["inicios del s. XX","Torneos estatales en la India"],["c. 1935","Se dice que empiezan torneos serios en Sri Lanka"],["1958","La India y Sri Lanka tienen federaciones oficiales"],["1988","Se funda en Chennai la Federación Internacional de Carrom"],["1991","Primer Campeonato del Mundo de Carrom"]],"figL":{"family":[["Carrom","India · sur de Asia"],["Crokinole","Canadá"],["Pichenotte","Canadá"],["Novuss","Letonia · Estonia"],["Couronne","Suecia · Dinamarca"]]}},"crokinole":{"title":"Apuntando al agujero del centro","lead":"El crokinole es muy querido en la Canadá rural. Se impulsan discos con un dedo sobre un tablero redondo de madera, apuntando al pequeño agujero del centro. El tablero más antiguo conocido es de 1876.","s":["El crokinole se juega en un tablero redondo de madera de unos 66 centímetros de diámetro. Juegan dos frente a frente, o cuatro por parejas, impulsando sus discos con un dedo hacia el centro.","El tablero tiene círculos marcados: desde fuera, anillos de 5, 10 y 15 puntos, y en el centro un pequeño agujero de 20. Ocho clavijas de madera rodean el anillo de 15 y cortan el camino directo.","No basta con apuntar al centro. Si hay un disco rival en el tablero, tu tiro debe tocar uno; si fallas, tu disco se retira.","El tablero más antiguo conocido lo hizo en 1876, en Ontario (Canadá), el artesano Eckhardt Wettlaufer, según se cuenta como regalo por el quinto cumpleaños de su hijo. Hoy está en un museo de Kitchener.","Se cree que el nombre viene del francés croquignole, «papirotazo». Desde 1999 se celebra cada junio un campeonato del mundo en Tavistock, donde vivió Wettlaufer."],"quiz":[["¿Cuántos puntos vale el agujero del centro del tablero de crokinole?","20","15","10","50"],["Si hay un disco rival en el tablero, ¿qué debe hacer tu tiro?","Tocar un disco rival","Entrar en el agujero central","Salir del tablero","Tocar una clavija"],["¿Cuándo y dónde se hizo el tablero de crokinole más antiguo conocido?","Canadá, 1876","Francia, 1776","Estados Unidos, 1926","Inglaterra, 1676"]],"kf":["Un tablero redondo de madera: se impulsan discos hacia los anillos de 5, 10 y 15 y el agujero de 20 del centro","Si hay un disco rival en el tablero hay que tocarlo; si fallas, se retira tu disco","El tablero más antiguo: Ontario (Canadá), 1876; campeonato del mundo desde 1999"],"more":[{"h":"Anillos, clavijas y foso","p":["Los discos se lanzan desde el anillo exterior de 5, dentro de tu propio cuarto. Fuera del borde corre un foso, donde acaban los discos que caen o se retiran.","Un disco que cae en el agujero de 20 se saca al instante y cuenta 20. Los discos que quedan en el tablero al final valen 5, 10 o 15 según el anillo, y normalmente solo se anota la diferencia entre ambos bandos."],"cap":["El tablero de crokinole: anillos de 5, 10 y 15 desde fuera y el agujero de 20 en el centro. Ocho clavijas protegen el anillo de 15, y un foso alrededor recoge los discos retirados"]},{"h":"Tocar, o ser retirado","p":["Si hay aunque sea un disco rival en el tablero, tu tiro debe tocar un disco rival, directamente o a través de otro disco. Si fallas, se retiran el disco lanzado y los discos tuyos que se movieron en ese tiro.","Cuando no hay discos rivales, muchas reglas exigen que el disco lanzado quede dentro del anillo de 15 o tocando su línea. Así nadie puede simplemente esconderse, y el juego se vuelve un duelo de ataque y defensa."],"cap":["La regla del tiro. Izquierda: con un disco rival (negro) en el tablero, basta con tocarlo con tu disco (rojo) (✓). Derecha: si fallas, tu disco se retira del tablero (×)"]},{"h":"De un tablero de Ontario a un campeonato del mundo","p":["Se dice que el primer registro canadiense se remonta a 1867, y en Estados Unidos Joshua K. Ingalls patentó un juego parecido en 1880. También se han señalado vínculos con juegos de golpe de Gran Bretaña y del sur de Asia, como el carrom.","A veces se dice que es un juego de menonitas o amish, pero se considera un error sin fundamento. Aun así, se cuenta que los menonitas de origen ruso lo disfrutaban con el nombre de Knipsbrat, «tabla de papirotazos»."],"cap":["El crokinole a lo largo del tiempo: del primer registro canadiense al tablero de Wettlaufer, una patente estadounidense y el campeonato del mundo de Tavistock"]},{"h":"Campeonatos y juego","p":["El campeonato del mundo se celebra desde 1999 el primer sábado de junio en Tavistock. En 2009 se fundó una asociación internacional, y hay clubes en toda Norteamérica y Europa.","El crokinole de este Atlas se juega solo en 3D, con varios aspectos de tablero a elegir. Pruébalo y disfruta del golpe de dedo, como en el carrom, y de apuntar a los anillos, como en los dardos."],"cap":[]}],"tl":[["1867","Se dice que es el primer registro canadiense"],["1876","Wettlaufer hace un tablero para su hijo"],["1880","En EE. UU., Ingalls patenta un juego parecido"],["1999","Comienza el campeonato del mundo en Tavistock"],["2009","Se funda una asociación internacional"]],"figL":{"time":[["1867","Canadá","Primer registro"],["1876","Ontario","El tablero más antiguo"],["1880","Estados Unidos","Patente de Ingalls"],["1999","Tavistock","Nace el mundial"],["2009","Internacional","Asociación internacional"]]}},"ugolki":{"title":"Salta, salta, hasta la esquina de enfrente","lead":"El ugolki ruso, el halma estadounidense y las «damas chinas» del tablero en estrella son una misma familia: no se captura nada, se salta sobre las piezas hasta que los dos ejércitos han cambiado de esquina.","s":["Ugolki significa «esquinas» en ruso. Blancas y negras colocan sus piezas en bloque en esquinas opuestas de un tablero de 8×8, y gana quien primero lleva todas sus piezas a la esquina del otro.","En cada jugada se avanza un paso a una casilla vecina vacía, o se salta sobre una pieza vecina hasta la casilla vacía justo detrás. Se puede saltar sobre piezas propias o del rival, y seguir saltando mientras se pueda. No se captura nada: las piezas saltadas se quedan en el tablero.","El juego más conocido de este tipo es el halma estadounidense. Se dice que lo ideó hacia 1883–84 el cirujano George Howard Monks, a partir de algunas ideas de un juego inglés llamado Hoppity. El nombre viene del griego «salto».","En 1892 apareció en Alemania una versión con tablero en estrella, el «Stern-Halma» (halma estrella). En 1928 la empresa estadounidense Pressman lo vendió como «Chinese checkers» (damas chinas) y causó furor; pero el juego no tiene nada que ver con China.","Nadie sabe con certeza cuándo nació el ugolki. Según una versión se inventó en Europa a finales del siglo XVIII, pero no se ha hallado ningún registro firme. Hoy lo disfrutan niños y adultos en Rusia y en los países de la antigua Unión Soviética."],"quiz":[["En el ugolki, ¿qué le pasa a una pieza saltada?","Se queda en el tablero","Se retira del tablero","Cambia de color","Vuelve a su esquina"],["¿Cuándo se vendió por primera vez como «damas chinas»?","En 1928, en EE. UU.","En 1892, en China","En el siglo XVIII, en la China Qing","En los años 1950, en Japón"],["¿Quién se dice que inventó el halma?","Monks, un cirujano estadounidense","Una juguetera alemana","Un matemático ruso","Un emperador chino"]],"kf":["De esquina a esquina en un tablero de 8×8: gana quien lleva antes todas sus piezas. No se captura nada","Un paso, o un salto sobre una pieza vecina —propia o rival—, y se puede seguir saltando","Halma (EE. UU., h. 1883–84) → Stern-Halma (Alemania, 1892) → «damas chinas» (1928). Nada chino"],"more":[{"h":"Avanzar saltando","p":["Al saltar da igual de quién sea la pieza. Alinea tus piezas como una «escalera», usa también las del rival como peldaños, y una sola jugada puede cruzar medio tablero.","Saltar nunca es obligatorio y se puede parar a mitad de camino. Pero no se puede combinar un paso y un salto en la misma jugada."],"cap":["Una cadena de saltos: la pieza blanca salta sobre una negra, una blanca, una negra y una blanca, cuatro saltos en una jugada (1–4). Todas las piezas saltadas siguen en el tablero"]},{"h":"El tablero y los campos del ugolki","p":["Los campos tienen varios tamaños: 3×3 (9 piezas), 3×4 (12) y 4×4 (16). En las reglas clásicas las piezas solo se mueven en línea recta, por filas y columnas; una variante permite también moverse en diagonal.","Si uno se queda en su propio campo, el rival nunca puede llenarlo. Por eso una regla muy usada en Rusia dice que pierde quien aún tenga una pieza en su campo después de la jugada 40. Si nada se decide en la jugada 80, decide el número de piezas en el campo rival."],"cap":["El tablero del ugolki: las blancas salen del campo de 3×4 abajo a la izquierda (a1–d3), las negras arriba a la derecha (e6–h8), y cada bando va hacia la esquina del otro (flechas). Los campos también pueden ser de 3×3 o 4×4"]},{"h":"La familia del halma","p":["El halma se juega en un tablero de 16×16, con 19 piezas por jugador si son dos o 13 si son cuatro, que se mueven en ocho direcciones. Monks obtuvo una patente estadounidense en 1888. Se dice que el matemático Thomas Hill, luego presidente de Harvard, le dio el nombre.","El tablero en estrella tiene 121 agujeros; cada jugador suele tener 10 piezas, y pueden jugar dos, tres, cuatro o seis. En China se llama tiaoqi, «ajedrez de saltos», y en Japón un juego parecido se conoce como «juego del diamante». También aquí, un rival que se queda en la esquina a la que vas puede impedirte llenarla."],"cap":["La familia de juegos de saltar y cambiar de esquina: el halma en un tablero de 16×16, el Stern-Halma y las «damas chinas» en la estrella, el ugolki en un tablero de 8×8"]},{"h":"Pruébalo","p":["Las reglas del ugolki se aprenden en un minuto. Pero construir largas escaleras también con las piezas del rival, sin dejarle peldaños a él, da para una profunda batalla de cálculo.","En este Atlas puedes jugar al ugolki con campos de 3×3, 3×4 o 4×4, o con movimientos en diagonal. El tablero 3D es de porcelana blanca y azul cobalto, como la cerámica rusa de Gzhel."],"cap":[]}],"tl":[["1883","Nace el halma (h. 1883–84, EE. UU.)"],["1888","Monks obtiene una patente estadounidense del halma"],["1892","Stern-Halma en tablero de estrella, en Alemania"],["1928","Se vende como «damas chinas» en EE. UU."],["1941","Milton Bradley obtiene los derechos del nombre"]],"figL":{"fam":[["h. 1883–84","Halma","EE. UU. · tablero de 16×16"],["1892","Stern-Halma","Alemania · tablero en estrella"],["1928","Damas chinas","un nombre nuevo en EE. UU."],["fecha incierta","Ugolki","Rusia · tablero de 8×8"]]}},"agon":{"title":"La reina al trono, los guardias a su alrededor","lead":"El agon se jugaba en la Inglaterra victoriana sobre un tablero de casillas hexagonales. Sienta a tu reina en el trono del centro y rodéala con tus seis guardias, y habrás ganado.","s":["El agon es un juego para dos, también llamado «La guardia de la reina». Su nombre es la palabra griega para «competición». El tablero tiene 91 casillas hexagonales, y la casilla del centro es el trono.","Cinco anillos rodean el trono, cada uno de un color distinto al siguiente. Cada jugador tiene una reina y seis guardias; gana quien sienta a su reina en el trono y ocupa con sus guardias las seis casillas que lo rodean.","Las piezas avanzan una casilla cada vez, por el mismo anillo o hacia el anillo interior. Nunca pueden ir hacia fuera: una vez que entran, no hay vuelta atrás. Solo una reina puede entrar en el trono.","El registro más antiguo conocido es un reglamento publicado en Londres en 1842. Se atribuye a Anthony Peacock, de Londres, y se disfrutaba en los hogares victorianos.","A menudo se dice que es el juego de tablero más antiguo conocido con casillas hexagonales. Una versión afirma que nació en la Francia del siglo XVIII, pero los tableros antiguos que se citan se consideran añadidos posteriores, así que no es seguro."],"quiz":[["¿Cómo se gana al agon?","Reina en el trono, rodeada por tus seis guardias","Capturando a la reina rival","Alineando todas tus piezas en el borde","Rodeando el trono vacío"],["¿Hacia dónde no puede moverse nunca una pieza del agon?","A un anillo exterior","Por el mismo anillo","Al anillo interior","Al trono (si es una reina)"],["¿Cuándo y dónde se publicaron por primera vez las reglas del agon?","Londres, 1842","París, 1742","Berlín, 1892","Nueva York, 1942"]],"kf":["91 casillas hexagonales: el trono en el centro y cinco anillos alrededor","Un paso por el mismo anillo o hacia dentro, nunca hacia fuera. Solo la reina ocupa el trono","Publicado en Londres en 1842; se le suele llamar el juego hexagonal más antiguo"],"more":[{"h":"Un tablero de trono y anillos","p":["En la salida estándar, las reinas y los guardias de ambos jugadores se alternan en el anillo exterior. En las reglas de 1842, las reinas empezaban en esquinas opuestas y los guardias se colocaban uno a uno, por turnos.","El tablero parece una diana, con anillos de colores alrededor del trono. Se ve de un vistazo en qué anillo está cada pieza, y así es fácil contar cuántos pasos le faltan para llegar al trono."],"cap":["El tablero del agon y la posición inicial. La casilla verde del centro es el trono, rodeado por cinco anillos rojos y marfil alternos. La reina (corona) y los seis guardias de cada bando se alternan por el borde"]},{"h":"Hacia dentro, siempre hacia dentro","p":["En cada turno se mueve una pieza un paso a una casilla vecina vacía, alrededor del mismo anillo o hacia dentro.","No se puede entrar en una casilla situada entre dos piezas rivales. Así, un muro de piezas enemigas es una barrera real en el camino hacia el centro."],"cap":["Cómo se mueve. El guardia blanco puede avanzar por su anillo o al anillo interior (verde), pero no volver hacia fuera (× rojo)"]},{"h":"Atrapado y expulsado","p":["Si atrapas una pieza rival en línea recta entre dos tuyas, queda capturada. Su dueño debe gastar el turno siguiente en devolver el guardia capturado a una casilla vacía del anillo exterior.","Una reina capturada vuelve a cualquier casilla vacía salvo el trono, y se mueve primero. Todos los pasos ganados con esfuerzo se pierden, así que la defensa importa mucho. Los detalles de las reglas varían un poco según el libro."],"cap":["Captura. (1) El guardia blanco avanza y atrapa en línea al guardia negro entre dos piezas blancas. (2) En el siguiente turno de su dueño, el guardia negro atrapado se lleva a una casilla vacía del borde"]},{"h":"Pruébalo","p":["Si tus seis guardias rodean el trono mientras está vacío, pierdes en el acto. ¿Mandar primero a la reina o abrir camino con los guardias? Planear el orden de las jugadas decide la partida.","En este Atlas puedes jugar al agon con la salida estándar por el borde o con la salida de 1842, colocando los guardias uno a uno. El tablero 3D es de caoba victoriana con filetes dorados, con piezas de hueso y ébano."],"cap":[]}],"tl":[["finales del s. XVIII","Una versión habla de un origen francés (sin pruebas firmes)"],["1842","Se publican en Londres las reglas de «Agon, or the Queen’s Guards»"],["siglo XIX","Popular en la Inglaterra victoriana; Jaques y otros venden tableros"],["1999","Descrito en la Oxford History of Board Games de Parlett"],["hoy","Incluido en Ludii, un sistema para estudiar juegos"]]}};
